INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C1','kor',3,1,'u1',2,'단원에서 배울 두 가지 — 감각적 표현의 재미를 느끼며 시 감상하기 · 표정 · 몸짓 · 목소리 · 말투로 표현하기 — 생생하게 표현하면 마음이 더 잘 전해짐',ARRAY['[4국05-04][4국01-03](차시 머리 표기 — 단원 도입)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C2','kor',3,1,'u1',2,'다섯 감각과 몸의 기관 — 눈으로 보고 · 귀로 듣고 · 코로 냄새 맡고 · 입으로 맛보고 · 손(피부)으로 만져 느낌',ARRAY['[4국05-04](차시 머리 표기 — 감각적 표현의 재미 느끼기)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C3','kor',3,1,'u1',2,'감각적 표현 — 보고 듣고 맛보고 냄새 맡고 만진 경험을 생생하게 나타낸 말 — 모양 · 소리 · 냄새 · 맛 · 느낌을 흉내 내거나 그려 냄 · 「풀밭」 · 「민들레」 같은 이름은 감각적 표현이 아님',ARRAY['[4국05-04](차시 머리 표기 — 감각적 표현의 재미 느끼기)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C4','kor',3,1,'u1',2,'시 속 감각적 표현 찾기 — 표현마다 어떤 감각으로 느낀 것인지 찾음(톡톡 = 듣는 소리 · 알록달록 = 보는 모습 · 향긋 = 맡는 냄새 · 달콤 = 맛 · 차갑다 = 피부)',ARRAY['[4국05-04](차시 머리 표기 — 감각적 표현의 재미 느끼기)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C5','kor',3,1,'u1',2,'감각적 표현을 쓰면 — 「꽃이 피었다」보다 장면이 생생하게 떠오르고 읽는 재미가 커짐 — 장면에 맞는 말이어야 함(많이 넣을수록 좋은 것 ✗)',ARRAY['[4국05-04](차시 머리 표기 — 감각적 표현의 재미 느끼기)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C6','kor',3,1,'u1',4,'낭송 — 시를 소리 내어 읽는 것 — 느낌을 살려 읽으면 더 생생함',ARRAY['[4국05-05](차시 머리 표기 — 느낌을 살려 시 낭송하기)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C7','kor',3,1,'u1',4,'흉내 내는 말 — 소리를 흉내 낸 말(휘잉휘잉 · 뽀드득)과 모양을 흉내 낸 말(빙글빙글 · 폴짝폴짝 · 사뿐사뿐)',ARRAY['[4국05-05](차시 머리 표기 — 느낌을 살려 시 낭송하기)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C8','kor',3,1,'u1',4,'흉내 내는 말의 뜻 — 사뿐사뿐 = 소리 없이 가볍게 내딛는 모양 · 폴짝폴짝 = 가볍게 자꾸 뛰어오르는 모양 · 소복소복 = 수북하게 쌓인 모양',ARRAY['[4국05-05](차시 머리 표기 — 느낌을 살려 시 낭송하기)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C9','kor',3,1,'u1',4,'낭송하는 방법 — 시의 분위기에 어울리는 목소리로 · 행과 행, 연과 연 사이는 쉬어 읽기 · 마음에 드는 부분은 강조 · 몸짓을 더해도 좋음',ARRAY['[4국05-05](차시 머리 표기 — 느낌을 살려 시 낭송하기)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C10','kor',3,1,'u1',4,'낭송하면 좋은 점 — 시의 리듬과 분위기를 느끼고 장면이 더 생생해지며 시 읽기가 즐거워짐',ARRAY['[4국05-05](차시 머리 표기 — 느낌을 살려 시 낭송하기)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C11','kor',3,1,'u1',6,'같은 말 다른 뜻 — 똑같은 「네」도 밝게(기쁘게 받아들임) · 놀라며(깜짝 놀람) · 작게(공손히 인정) — 목소리와 말투에 따라 뜻이 달라짐',ARRAY['[4국01-03](차시 머리 표기 — 상황에 맞는 목소리 · 말투)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C12','kor',3,1,'u1',6,'상황에 맞는 목소리 · 말투 — 칭찬 = 밝고 자신 있게 · 잘못을 깨달음 = 공손하고 작게 · 반가움 = 신나게 · 도움을 청함 = 다정하게 — 크고 밝은 목소리가 언제나 맞지는 않음',ARRAY['[4국01-03](차시 머리 표기 — 상황에 맞는 목소리 · 말투)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C13','kor',3,1,'u1',6,'알맞은 목소리 · 말투의 좋은 점 — 내 마음을 정확히 전하고 상대의 마음을 배려하며 서로의 처지를 이해함',ARRAY['[4국01-03](차시 머리 표기 — 상황에 맞는 목소리 · 말투)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C14','kor',3,1,'u1',7,'표정 · 몸짓 · 목소리로 전하는 마음 — 말뿐 아니라 표정 · 몸짓 · 목소리 · 말투로도 마음을 전함 — 「괜찮아」도 웃으며 하면 다정하게, 찡그리며 하면 차갑게 들림',ARRAY['[4국01-03][4국01-04](차시 머리 표기 — 표정 · 몸짓 · 목소리로 대화하기)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C15','kor',3,1,'u1',7,'행동에서 마음 짐작하기 — 고개를 숙이고 떨리는 작은 목소리 = 무섭고 걱정됨 · 두 팔을 번쩍 = 해냄 · 어깨를 토닥임 = 응원 — 인물의 표정 · 몸짓 · 목소리를 살펴 마음을 짐작',ARRAY['[4국01-03][4국01-04](차시 머리 표기 — 표정 · 몸짓 · 목소리로 대화하기)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C16','kor',3,1,'u1',7,'마음에 맞게 대화하기 — 응원 · 위로할 때는 환한 표정 · 다정한 목소리 · 토닥이는 몸짓 — 눈 흘기기 · 등 돌리기 ✗ · 말과 표정이 어긋나지 않게',ARRAY['[4국01-03][4국01-04](차시 머리 표기 — 표정 · 몸짓 · 목소리로 대화하기)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C17','kor',3,1,'u1',9,'역할놀이 — 상황 속 인물이 되어 알맞은 표정 · 몸짓 · 목소리 · 말투로 대화하는 것',ARRAY['[4국01-03][4국01-04](차시 머리 표기 — 표정 · 몸짓 · 목소리로 대화하기)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C18','kor',3,1,'u1',9,'역할놀이 준비하기 — 상황 카드 살피기 → 상황에 어울리는 표현 정하기 → 역할과 주고받을 대사 정하기',ARRAY['[4국01-03][4국01-04](차시 머리 표기 — 표정 · 몸짓 · 목소리로 대화하기)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C19','kor',3,1,'u1',9,'역할놀이에서 지킬 점 — 상황에 맞게 실감 나게 · 또렷한 목소리로 · 언어 예절 지키기 — 친구 비웃기 · 대충 장난치기 ✗ · 좋은 점: 표현 연습 · 상대 마음 이해 · 실제 대화에 자신감',ARRAY['[4국01-03][4국01-04](차시 머리 표기 — 표정 · 몸짓 · 목소리로 대화하기)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C20','kor',3,1,'u1',11,'배운 것 실천하기 — 감각적 표현이 담긴 시로 낭송회 열기 · 그림 속 상황을 보고 알맞은 표정 · 목소리로 대화 만들기 놀이',ARRAY['단원 통합 실천(차시 머리 표기 — 번호 없음, W7)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C21','kor',3,1,'u1',11,'친구와 협동하기 — 서로의 표현을 보고 잘한 점은 칭찬하고 고칠 점은 도와줌 — 놀리기 ✗',ARRAY['단원 통합 실천(차시 머리 표기 — 번호 없음, W7)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C22','kor',3,1,'u1',11,'장면에 어울리는 감각적 표현 — 같은 장면도 표현에 따라 느낌이 달라짐(바람이 솔솔 → 깃발이 살랑 / 씽씽 → 크게 펄럭) · 장면을 감각을 살려 설명(파도가 철썩철썩)',ARRAY['[4국05-04](차시 머리 표기 — 감각적 표현의 재미 느끼기)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C23','kor',3,1,'u1',11,'받침을 이어 읽기 — 받침 뒤에 뜻 없는 ㅇ(조사 · 끝)이 오면 받침소리를 그대로 이어 읽음 — 꽃이 [꼬치] · 무릎을 [무르플] · 부엌에서 [부어케서]',ARRAY['받침을 이어 읽는 낱말 발음하기(성취기준 번호 확인 필요)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C24','kor',3,1,'u1',11,'뜻 있는 낱말 앞에서 이어 읽기 — 받침 뒤에 뜻 있는 낱말(안 · 위)이 오면 대표 소리로 바꿔 이어 읽음 — 부엌 안 [부어간] · 무릎 위 [무르뷔]',ARRAY['받침을 이어 읽는 낱말 발음하기(성취기준 번호 확인 필요)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u1-C25','kor',3,1,'u1',11,'쓸 때는 글자 그대로 · 또박또박 — 읽을 때 소리가 이어져도 쓸 때는 원래 글자대로(꽃이) · 글씨는 한 칸씩 또박또박 바르게',ARRAY['바르게 글씨 쓰기(성취기준 번호 확인 필요)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
