INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X03','kor',3,'u1',ARRAY['K3-1-u1-C4','K3-1-u1-C22']::text[],'감각적 표현에 담긴 감각을 잘못 안다(톡톡을 보는 모습으로)','어떤 감각으로 느꼈나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X04','kor',3,'u1',ARRAY['K3-1-u1-C5']::text[],'감각적 표현을 써도 쓰지 않은 말과 다를 바 없다고 여긴다','장면이 더 생생해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X05','kor',3,'u1',ARRAY['K3-1-u1-C5','K3-1-u1-C22']::text[],'감각적 표현은 많이 넣을수록 좋다고 여겨 장면과 맞지 않는 말을 억지로 넣는다','장면에 맞는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X06','kor',3,'u1',ARRAY['K3-1-u1-C3','K3-1-u1-C4']::text[],'감각적 표현은 보는 모양과 듣는 소리만이라고 여겨 냄새 · 맛 · 촉감을 빠뜨린다','다섯 감각 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X07','kor',3,'u1',ARRAY['K3-1-u1-C7']::text[],'소리를 흉내 낸 말과 모양을 흉내 낸 말을 바꾸어 안다','소리일까, 모양일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X08','kor',3,'u1',ARRAY['K3-1-u1-C8']::text[],'흉내 내는 말의 뜻을 반대로 안다(사뿐사뿐 = 쿵쿵 세게)','어떤 모양일까요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X09','kor',3,'u1',ARRAY['K3-1-u1-C6','K3-1-u1-C9']::text[],'낭송을 눈으로만 읽기나 아주 빠르게 한 번에 읽기로 여긴다','소리 내어 느낌을 살려') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X10','kor',3,'u1',ARRAY['K3-1-u1-C9','K3-1-u1-C10','K3-1-u1-C20']::text[],'시의 분위기와 맞지 않는 목소리로 낭송한다(신나는 시를 슬프게)','시의 분위기에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X11','kor',3,'u1',ARRAY['K3-1-u1-C9']::text[],'행과 행, 연과 연 사이를 쉬지 않고 붙여 읽는다','사이는 쉬어 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X12','kor',3,'u1',ARRAY['K3-1-u1-C11']::text[],'같은 말은 목소리 · 말투가 달라도 뜻이 늘 같다고 여긴다','목소리에 따라 뜻이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X13','kor',3,'u1',ARRAY['K3-1-u1-C12','K3-1-u1-C18']::text[],'상황(칭찬 · 잘못 · 반가움 · 다침)과 어울리지 않는 목소리 · 말투를 고른다','그때 마음은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X14','kor',3,'u1',ARRAY['K3-1-u1-C12']::text[],'크고 밝은 목소리가 어느 상황에서나 가장 좋다고 여긴다','언제나 크게? 상황에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X15','kor',3,'u1',ARRAY['K3-1-u1-C13']::text[],'알맞은 목소리 · 말투를 쓰는 좋은 점(정확히 전함 · 배려 · 이해)을 모른다','마음을 정확히, 서로 배려') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X16','kor',3,'u1',ARRAY['K3-1-u1-C1','K3-1-u1-C14']::text[],'말만 하면 되고 표정 · 몸짓은 마음 전하기와 상관없다고 여긴다','표정 · 몸짓도 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X17','kor',3,'u1',ARRAY['K3-1-u1-C15']::text[],'표정 · 몸짓 · 목소리에 드러난 마음을 잘못 짐작한다(고개를 푹 숙임 = 신남)','몸이 어떤가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X18','kor',3,'u1',ARRAY['K3-1-u1-C14','K3-1-u1-C16']::text[],'말의 내용과 표정 · 목소리가 어긋나도 마음이 잘 전해진다고 여긴다','말과 표정을 맞춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X19','kor',3,'u1',ARRAY['K3-1-u1-C16']::text[],'응원 · 위로할 때 어울리지 않는 표현(눈 흘기기 · 등 돌리기 · 화난 목소리)을 고른다','힘을 주는 표현') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X20','kor',3,'u1',ARRAY['K3-1-u1-C17','K3-1-u1-C19']::text[],'역할놀이를 웃기거나 친구를 비웃는 장난으로 여긴다','인물이 되어 실감 나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X21','kor',3,'u1',ARRAY['K3-1-u1-C18','K3-1-u1-C19']::text[],'역할 · 대사를 정하지 않고 시작하거나 웅얼거려 언어 예절과 전달을 지키지 않는다','준비하고 또렷하게, 예절 지켜') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X22','kor',3,'u1',ARRAY['K3-1-u1-C21']::text[],'친구의 표현을 놀리거나 잘한 점을 칭찬하지 않고 혼자만 하려 한다','칭찬하고 도와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X23','kor',3,'u1',ARRAY['K3-1-u1-C23']::text[],'받침 뒤에 뜻 없는 ㅇ이 와도 글자 그대로 끊어 읽는다([꽃이] · [꼳이])','받침을 이어 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X24','kor',3,'u1',ARRAY['K3-1-u1-C24']::text[],'뜻 있는 낱말(안 · 위) 앞에서도 받침을 그대로 넘겨 읽는다([부어칸] · [무르퓌])','안 · 위 앞에서는 바꿔서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X25','kor',3,'u1',ARRAY['K3-1-u1-C25']::text[],'이어 읽은 소리대로 글자도 바꾸어 쓰거나 글씨를 아무렇게나 쓴다(꼬치라고 씀)','쓸 때는 글자 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u1-X26','kor',3,'u1',ARRAY['K3-1-u1-C1','K3-1-u1-C22']::text[],'생생하게 표현하는 방법은 한 가지뿐이고 같은 장면은 표현도 하나뿐이라고 여긴다','표현 방법은 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
