INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L02_challenge#7','kor',3,1,'u1','L02','g3_1_kor_u1_L02_challenge','lesson_challenge','K3-1-u1-C2',3,'mc','auto','「군침이 도는 고소한 냄새」를 느낀 기관과 감각을 바르게 짝지은 것은 무엇일까요?',ARRAY['K3-1-u1-X01']::text[],false,'{"seq":7,"concept":"K3-1-u1-C2","difficulty":3,"kind":"mc","stem":"「군침이 도는 고소한 냄새」를 느낀 기관과 감각을 바르게 짝지은 것은 무엇일까요?","options":[{"t":"코 — 냄새 맡기","correct":true},{"t":"귀 — 냄새 맡기","mis":"K3-1-u1-X01"},{"t":"눈 — 듣기","mis":"K3-1-u1-X01"},{"t":"손 — 맛보기","mis":"K3-1-u1-X01"}],"explanation":["냄새","코","짝"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L02_challenge#8','kor',3,1,'u1','L02','g3_1_kor_u1_L02_challenge','lesson_challenge','K3-1-u1-C4',4,'essay','teacher','「비 오는 날」에서 감각적 표현 두 가지를 찾아, 각각 어떤 감각으로 느낀 것인지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u1-C4","difficulty":4,"kind":"essay","stem":"「비 오는 날」에서 감각적 표현 두 가지를 찾아, 각각 어떤 감각으로 느낀 것인지 쓰세요.","answer_guide":{"answer":"예: 「톡톡 토독」은 귀로 들은 빗방울 소리이다. 「젖은 흙냄새가 코끝에 솔솔」은 코로 맡은 냄새이다.","scoring_points":["감각적 표현 두 가지를 찾았는가","감각을 바르게 짝지었는가","시에 있는 말로 썼는가"]},"explanation":["표현","감각","짝짓기"],"asset":{"type":"passage","lines":["창밖에 빗방울이 톡톡 토독","우산들이 알록달록 꽃처럼 피고","젖은 흙냄새가 코끝에 솔솔","손등에 닿은 빗물은 차갑고 시원해"],"title":"비 오는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L02_challenge#9','kor',3,1,'u1','L02','g3_1_kor_u1_L02_challenge','lesson_challenge','K3-1-u1-C5',4,'essay','teacher','「급식이 맛있었다.」를 감각적 표현을 살려 생생한 문장으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u1-C5","difficulty":4,"kind":"essay","stem":"「급식이 맛있었다.」를 감각적 표현을 살려 생생한 문장으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 갓 지은 밥에서 고소한 냄새가 모락모락 나고, 바삭바삭한 튀김을 한 입 베어 무니 입안이 행복했다.","scoring_points":["감각적 표현을 넣었는가","두 가지 이상의 감각을 살렸는가","장면에 어울리는가"]},"explanation":["냄새","소리 · 맛","생생하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L02_challenge#10','kor',3,1,'u1','L02','g3_1_kor_u1_L02_challenge','lesson_challenge','K3-1-u1-C3',4,'essay','teacher','내가 좋아하는 계절의 한 장면을 떠올려 서로 다른 감각을 살린 감각적 표현 세 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u1-C3","difficulty":4,"kind":"essay","stem":"내가 좋아하는 계절의 한 장면을 떠올려 서로 다른 감각을 살린 감각적 표현 세 가지를 쓰세요.","answer_guide":{"answer":"예: 가을 — 바스락바스락 낙엽 밟는 소리, 울긋불긋 물든 단풍잎, 코끝이 찡하게 시원한 바람.","scoring_points":["감각적 표현 세 가지를 썼는가","서로 다른 감각을 살렸는가","장면에 어울리는가"]},"explanation":["소리","모습","느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
