INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L04_challenge#3','kor',3,1,'u1','L04','g3_1_kor_u1_L04_challenge','lesson_challenge','K3-1-u1-C7',3,'mc','auto','시우는 「뽀드득뽀드득은 눈이 쌓인 모양을 흉내 낸 말이야.」라고 했어요. 알맞게 고친 말은 무엇일까요?',ARRAY['K3-1-u1-X07','K3-1-u1-X03','K3-1-u1-X02']::text[],false,'{"seq":3,"concept":"K3-1-u1-C7","difficulty":3,"kind":"mc","stem":"시우는 「뽀드득뽀드득은 눈이 쌓인 모양을 흉내 낸 말이야.」라고 했어요. 알맞게 고친 말은 무엇일까요?","options":[{"t":"「눈을 밟을 때 나는 소리를 흉내 낸 말이야.」","correct":true},{"t":"「맞아, 쌓인 모양이야.」","mis":"K3-1-u1-X07"},{"t":"「눈의 냄새를 흉내 낸 말이야.」","mis":"K3-1-u1-X03"},{"t":"「흉내 내는 말이 아니야.」","mis":"K3-1-u1-X02"}],"explanation":["밟을 때","들리는","소리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
