INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L04_challenge#8','kor',3,1,'u1','L04','g3_1_kor_u1_L04_challenge','lesson_challenge','K3-1-u1-C7',4,'essay','teacher','「눈 오는 운동장」에서 소리를 흉내 낸 말과 모양을 흉내 낸 말을 하나씩 찾아 쓰고, 그렇게 나눈 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u1-C7","difficulty":4,"kind":"essay","stem":"「눈 오는 운동장」에서 소리를 흉내 낸 말과 모양을 흉내 낸 말을 하나씩 찾아 쓰고, 그렇게 나눈 까닭을 쓰세요.","answer_guide":{"answer":"예: 소리를 흉내 낸 말 — 뽀드득뽀드득(눈을 밟을 때 나는 소리). 모양을 흉내 낸 말 — 소복소복(눈이 수북하게 쌓인 모양).","scoring_points":["소리를 흉내 낸 말을 찾았는가","모양을 흉내 낸 말을 찾았는가","까닭을 썼는가"]},"explanation":["소리","모양","까닭"],"asset":{"type":"passage","lines":["— 1연 —","사락사락 하얀 눈이 내려요","소복소복 운동장에 쌓여요","— 2연 —","뽀드득뽀드득 발자국 찍고","데굴데굴 눈덩이를 굴려요"],"title":"눈 오는 운동장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L04_challenge#9','kor',3,1,'u1','L04','g3_1_kor_u1_L04_challenge','lesson_challenge','K3-1-u1-C9',4,'essay','teacher','「눈 오는 운동장」을 낭송할 계획을 목소리 · 쉬어 읽을 곳 · 강조할 부분으로 나누어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u1-C9","difficulty":4,"kind":"essay","stem":"「눈 오는 운동장」을 낭송할 계획을 목소리 · 쉬어 읽을 곳 · 강조할 부분으로 나누어 쓰세요.","answer_guide":{"answer":"예: 목소리 — 눈 오는 날의 설렘이 느껴지게 신나고 밝게. 쉬어 읽을 곳 — 1연과 2연 사이. 강조할 부분 — 「뽀드득뽀드득」을 발자국을 찍듯 또박또박 힘주어.","scoring_points":["목소리를 정했는가","쉬어 읽을 곳을 정했는가","강조할 부분을 정했는가"]},"explanation":["목소리","쉬기","강조"],"asset":{"type":"passage","lines":["— 1연 —","사락사락 하얀 눈이 내려요","소복소복 운동장에 쌓여요","— 2연 —","뽀드득뽀드득 발자국 찍고","데굴데굴 눈덩이를 굴려요"],"title":"눈 오는 운동장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L04_challenge#10','kor',3,1,'u1','L04','g3_1_kor_u1_L04_challenge','lesson_challenge','K3-1-u1-C8',4,'essay','teacher','흉내 내는 말 두 가지를 넣어 우리 반 쉬는 시간 모습을 짧은 시 두 줄로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u1-C8","difficulty":4,"kind":"essay","stem":"흉내 내는 말 두 가지를 넣어 우리 반 쉬는 시간 모습을 짧은 시 두 줄로 쓰세요.","answer_guide":{"answer":"예: 공이 통통 튀어 오르고 / 친구들이 우르르 뛰어나가요.","scoring_points":["흉내 내는 말 두 가지를 넣었는가","장면에 어울리는가","두 줄로 썼는가"]},"explanation":["흉내 내는 말","장면","두 줄"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
