INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_basic#9','kor',3,1,'u1','L06','g3_1_kor_u1_L06_basic','lesson_basic','K3-1-u1-C12',2,'mc','auto','선생님께 「복도에서 뛰면 다칠 수 있단다.」라는 말을 들었을 때 알맞은 대답은 무엇일까요?',ARRAY['K3-1-u1-X14','K3-1-u1-X13','K3-1-u1-X15']::text[],false,'{"seq":9,"concept":"K3-1-u1-C12","difficulty":2,"kind":"mc","stem":"선생님께 「복도에서 뛰면 다칠 수 있단다.」라는 말을 들었을 때 알맞은 대답은 무엇일까요?","options":[{"t":"(작고 공손하게) 「네, 조심할게요.」","correct":true},{"t":"(크게 신나서) 「네!」","mis":"K3-1-u1-X14"},{"t":"(짜증 내며) 「알아요.」","mis":"K3-1-u1-X13"},{"t":"(못 들은 척) 대답하지 않음","mis":"K3-1-u1-X15"}],"explanation":["주의를 들음","뉘우침","공손하게"],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 청소를 아주 깨끗하게 했구나!"},{"who":"시우","text":"(밝고 자신 있게) 네!"},{"who":"선생님","text":"복도에서 뛰면 다칠 수 있단다."},{"who":"시우","text":"(작고 공손하게) 네…."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_basic#10','kor',3,1,'u1','L06','g3_1_kor_u1_L06_basic','lesson_basic','K3-1-u1-C12',3,'mc','auto','「크고 밝은 목소리가 언제나 가장 좋아.」에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u1-X14','K3-1-u1-X12']::text[],false,'{"seq":10,"concept":"K3-1-u1-C12","difficulty":3,"kind":"mc","stem":"「크고 밝은 목소리가 언제나 가장 좋아.」에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"상황에 따라 공손하거나 다정한 목소리가 더 알맞을 때도 있어요.","correct":true},{"t":"맞아요, 언제나 크고 밝게 말해야 해요.","mis":"K3-1-u1-X14"},{"t":"목소리는 아무래도 좋아요.","mis":"K3-1-u1-X12"},{"t":"작은 목소리는 언제나 잘못이에요.","mis":"K3-1-u1-X14"}],"explanation":["언제나?","상황에 맞게","골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#1','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C11',2,'mc','auto','「잘했다.」를 비꼬는 말투로 하면 어떻게 들릴까요?',ARRAY['K3-1-u1-X12','K3-1-u1-X15']::text[],false,'{"seq":1,"concept":"K3-1-u1-C11","difficulty":2,"kind":"mc","stem":"「잘했다.」를 비꼬는 말투로 하면 어떻게 들릴까요?","options":[{"t":"칭찬이 아니라 놀리는 말로 들려요.","correct":true},{"t":"똑같이 칭찬으로 들려요.","mis":"K3-1-u1-X12"},{"t":"아무 뜻도 없어요.","mis":"K3-1-u1-X12"},{"t":"더 따뜻하게 들려요.","mis":"K3-1-u1-X15"}],"explanation":["같은 말","말투가 다르면","뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#2','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C12',2,'mc','auto','동생이 아끼던 장난감이 부서져 울고 있어요. 어울리는 말투는 무엇일까요?',ARRAY['K3-1-u1-X13','K3-1-u1-X14']::text[],false,'{"seq":2,"concept":"K3-1-u1-C12","difficulty":2,"kind":"mc","stem":"동생이 아끼던 장난감이 부서져 울고 있어요. 어울리는 말투는 무엇일까요?","options":[{"t":"다정하고 부드러운 말투로 「속상하지?」","correct":true},{"t":"크게 웃으며 「그것 봐!」","mis":"K3-1-u1-X13"},{"t":"짜증 내며 「그만 울어.」","mis":"K3-1-u1-X13"},{"t":"신나게 「괜찮아!」만 외치기","mis":"K3-1-u1-X14"}],"explanation":["슬픈 동생","위로","다정하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#3','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C12',3,'mc','auto','도서관에서 친구에게 책 위치를 물어볼 때 알맞은 목소리는 무엇일까요?',ARRAY['K3-1-u1-X14','K3-1-u1-X13']::text[],false,'{"seq":3,"concept":"K3-1-u1-C12","difficulty":3,"kind":"mc","stem":"도서관에서 친구에게 책 위치를 물어볼 때 알맞은 목소리는 무엇일까요?","options":[{"t":"작고 또렷한 목소리","correct":true},{"t":"운동장에서처럼 크게 외치는 목소리","mis":"K3-1-u1-X14"},{"t":"웅얼거려 알아들을 수 없는 목소리","mis":"K3-1-u1-X13"},{"t":"화난 목소리","mis":"K3-1-u1-X13"}],"explanation":["도서관","조용한 곳","작고 또렷하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#4','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C11',3,'mc','auto','같은 말이라도 목소리 · 말투에 따라 뜻이 달라지는 예로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X12','K3-1-u1-X14']::text[],false,'{"seq":4,"concept":"K3-1-u1-C11","difficulty":3,"kind":"mc","stem":"같은 말이라도 목소리 · 말투에 따라 뜻이 달라지는 예로 알맞은 것은 무엇일까요?","options":[{"t":"「고마워.」를 웃으며 하면 진심, 퉁명스럽게 하면 억지로 하는 말처럼 들린다","correct":true},{"t":"「고마워.」는 어떻게 말해도 늘 같은 뜻이다","mis":"K3-1-u1-X12"},{"t":"「고마워.」는 글자로 써야만 뜻이 있다","mis":"K3-1-u1-X12"},{"t":"「고마워.」는 크게 말할수록 뜻이 좋아진다","mis":"K3-1-u1-X14"}],"explanation":["같은 말","다른 말투","다른 뜻"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#5','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C13',3,'mc','auto','친구에게 공손하고 다정한 말투로 부탁했더니 친구가 기분 좋게 도와주었어요. 이 일에서 알 수 있는 것은 무엇일까요?',ARRAY['K3-1-u1-X15','K3-1-u1-X14']::text[],false,'{"seq":5,"concept":"K3-1-u1-C13","difficulty":3,"kind":"mc","stem":"친구에게 공손하고 다정한 말투로 부탁했더니 친구가 기분 좋게 도와주었어요. 이 일에서 알 수 있는 것은 무엇일까요?","options":[{"t":"알맞은 말투는 상대를 배려하고 마음을 잘 전해요.","correct":true},{"t":"말투는 상관없어요.","mis":"K3-1-u1-X15"},{"t":"크게 소리쳐야 도와줘요.","mis":"K3-1-u1-X14"},{"t":"부탁은 말투와 상관없이 늘 들어줘요.","mis":"K3-1-u1-X15"}],"explanation":["다정한 말투","배려","마음 전하기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#6','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C12',3,'mc','auto','시우가 주의를 듣고도 「네!」를 크게 신나서 말했다면 선생님은 어떻게 느끼실까요?',ARRAY['K3-1-u1-X13','K3-1-u1-X12','K3-1-u1-X14']::text[],false,'{"seq":6,"concept":"K3-1-u1-C12","difficulty":3,"kind":"mc","stem":"시우가 주의를 듣고도 「네!」를 크게 신나서 말했다면 선생님은 어떻게 느끼실까요?","options":[{"t":"잘못을 가볍게 여긴다고 느끼실 수 있어요.","correct":true},{"t":"잘 뉘우쳤다고 느끼세요.","mis":"K3-1-u1-X13"},{"t":"아무렇지 않으세요.","mis":"K3-1-u1-X12"},{"t":"크게 말해서 언제나 좋아하세요.","mis":"K3-1-u1-X14"}],"explanation":["상황과","말투가 어긋나면","마음이 잘못 전해져요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"오늘 청소를 아주 깨끗하게 했구나!"},{"who":"시우","text":"(밝고 자신 있게) 네!"},{"who":"선생님","text":"복도에서 뛰면 다칠 수 있단다."},{"who":"시우","text":"(작고 공손하게) 네…."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#7','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C13',3,'mc','auto','상황에 맞는 목소리 · 말투에 대해 가장 바르게 말한 친구는 누구일까요?',ARRAY['K3-1-u1-X15','K3-1-u1-X14','K3-1-u1-X12']::text[],false,'{"seq":7,"concept":"K3-1-u1-C13","difficulty":3,"kind":"mc","stem":"상황에 맞는 목소리 · 말투에 대해 가장 바르게 말한 친구는 누구일까요?","options":[{"t":"「상황과 듣는 사람을 생각해서 목소리와 말투를 골라야 해.」","correct":true},{"t":"「내 기분대로만 말하면 돼.」","mis":"K3-1-u1-X15"},{"t":"「목소리는 크면 클수록 좋아.」","mis":"K3-1-u1-X14"},{"t":"「말투가 달라도 뜻은 늘 같아.」","mis":"K3-1-u1-X12"}],"explanation":["상황","듣는 사람","골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#8','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C11',4,'essay','teacher','「응.」이라는 같은 말을 서로 다른 두 상황에서 어떤 목소리로 말할지 쓰고, 뜻이 어떻게 달라지는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u1-C11","difficulty":4,"kind":"essay","stem":"「응.」이라는 같은 말을 서로 다른 두 상황에서 어떤 목소리로 말할지 쓰고, 뜻이 어떻게 달라지는지 쓰세요.","answer_guide":{"answer":"예: 친구가 같이 놀자고 할 때는 밝고 신나게 「응!」 하면 좋다는 뜻이다. 엄마가 숙제했느냐고 물으실 때 숙제를 못 했으면 작고 미안한 목소리로 「응….」 하면 미안한 마음이 담긴다.","scoring_points":["두 상황을 썼는가","상황마다 목소리를 썼는가","뜻이 달라짐을 썼는가"]},"explanation":["같은 말","두 상황","다른 뜻"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#9','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C12',4,'essay','teacher','할머니께서 생신 선물을 받고 고마워하실 때, 내가 할 말과 어울리는 목소리 · 말투를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u1-C12","difficulty":4,"kind":"essay","stem":"할머니께서 생신 선물을 받고 고마워하실 때, 내가 할 말과 어울리는 목소리 · 말투를 쓰세요.","answer_guide":{"answer":"예: 「할머니, 생신 축하드려요! 오래오래 건강하세요.」라고 밝고 다정한 목소리, 공손한 말투로 말한다.","scoring_points":["할 말을 썼는가","어울리는 목소리를 썼는가","공손한 말투가 드러나는가"]},"explanation":["상황","목소리","말투"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L06_challenge#10','kor',3,1,'u1','L06','g3_1_kor_u1_L06_challenge','lesson_challenge','K3-1-u1-C13',4,'essay','teacher','알맞은 목소리 · 말투로 말하면 좋은 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u1-C13","difficulty":4,"kind":"essay","stem":"알맞은 목소리 · 말투로 말하면 좋은 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 내 마음을 정확하게 전할 수 있다. 듣는 사람의 마음을 배려해서 서로 기분 좋게 대화할 수 있다.","scoring_points":["좋은 점 두 가지를 썼는가","마음을 정확히 전함을 썼는가","배려나 이해를 썼는가"]},"explanation":["정확히","배려","두 가지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
