INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L07_basic#5','kor',3,1,'u1','L07','g3_1_kor_u1_L07_basic','lesson_basic','K3-1-u1-C15',2,'mc','auto','「처음 타는 두발자전거」에서 처음에 예린이의 마음은 어땠을까요?',ARRAY['K3-1-u1-X17']::text[],false,'{"seq":5,"concept":"K3-1-u1-C15","difficulty":2,"kind":"mc","stem":"「처음 타는 두발자전거」에서 처음에 예린이의 마음은 어땠을까요?","options":[{"t":"넘어질까 봐 걱정되고 무서웠다","correct":true},{"t":"하나도 걱정되지 않고 신났다","mis":"K3-1-u1-X17"},{"t":"지호에게 화가 났다","mis":"K3-1-u1-X17"},{"t":"자전거가 지루했다","mis":"K3-1-u1-X17"}],"explanation":["입술을 깨묾","손이 떨림","목소리가 작아짐"],"asset":{"type":"passage","lines":["예린이는 자전거 앞에서 입술을 꼭 깨물었어요.","손잡이를 잡은 손이 덜덜 떨렸어요.","「넘어지면 어떡하지?」 목소리가 점점 작아졌어요.","지호가 뒤에서 안장을 잡아 주며 씩 웃었어요.","「내가 꼭 잡고 있을게. 천천히 가 보자!」","몇 바퀴를 돈 뒤, 예린이는 두 팔을 번쩍 들었어요.","「나 혼자 탔어!」"],"title":"처음 타는 두발자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
