INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L07_basic#10','kor',3,1,'u1','L07','g3_1_kor_u1_L07_basic','lesson_basic','K3-1-u1-C15',3,'mc','auto','「처음 타는 두발자전거」에서 예린이의 마음은 어떻게 바뀌었을까요?',ARRAY['K3-1-u1-X17']::text[],false,'{"seq":10,"concept":"K3-1-u1-C15","difficulty":3,"kind":"mc","stem":"「처음 타는 두발자전거」에서 예린이의 마음은 어떻게 바뀌었을까요?","options":[{"t":"걱정되고 무서움 → 해내서 기쁨","correct":true},{"t":"기쁨 → 무서움","mis":"K3-1-u1-X17"},{"t":"처음부터 끝까지 무서움","mis":"K3-1-u1-X17"},{"t":"화남 → 졸림","mis":"K3-1-u1-X17"}],"explanation":["처음","끝","두 팔 번쩍"],"asset":{"type":"passage","lines":["예린이는 자전거 앞에서 입술을 꼭 깨물었어요.","손잡이를 잡은 손이 덜덜 떨렸어요.","「넘어지면 어떡하지?」 목소리가 점점 작아졌어요.","지호가 뒤에서 안장을 잡아 주며 씩 웃었어요.","「내가 꼭 잡고 있을게. 천천히 가 보자!」","몇 바퀴를 돈 뒤, 예린이는 두 팔을 번쩍 들었어요.","「나 혼자 탔어!」"],"title":"처음 타는 두발자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L07_challenge#1','kor',3,1,'u1','L07','g3_1_kor_u1_L07_challenge','lesson_challenge','K3-1-u1-C16',2,'mc','auto','「내가 꼭 잡고 있을게. 천천히 가 보자!」를 말할 때 지호에게 어울리는 목소리는 무엇일까요?',ARRAY['K3-1-u1-X19']::text[],false,'{"seq":1,"concept":"K3-1-u1-C16","difficulty":2,"kind":"mc","stem":"「내가 꼭 잡고 있을게. 천천히 가 보자!」를 말할 때 지호에게 어울리는 목소리는 무엇일까요?","options":[{"t":"다정하고 힘을 주는 목소리","correct":true},{"t":"귀찮아하는 목소리","mis":"K3-1-u1-X19"},{"t":"비웃는 목소리","mis":"K3-1-u1-X19"},{"t":"화난 목소리","mis":"K3-1-u1-X19"}],"explanation":["응원하는 말","다정하게","힘을 주는"],"asset":{"type":"passage","lines":["예린이는 자전거 앞에서 입술을 꼭 깨물었어요.","손잡이를 잡은 손이 덜덜 떨렸어요.","「넘어지면 어떡하지?」 목소리가 점점 작아졌어요.","지호가 뒤에서 안장을 잡아 주며 씩 웃었어요.","「내가 꼭 잡고 있을게. 천천히 가 보자!」","몇 바퀴를 돈 뒤, 예린이는 두 팔을 번쩍 들었어요.","「나 혼자 탔어!」"],"title":"처음 타는 두발자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L07_challenge#2','kor',3,1,'u1','L07','g3_1_kor_u1_L07_challenge','lesson_challenge','K3-1-u1-C14',2,'mc','auto','지호는 「말만 잘하면 되지 표정은 상관없어.」라고 했어요. 알맞게 고친 말은 무엇일까요?',ARRAY['K3-1-u1-X16','K3-1-u1-X26','K3-1-u1-X14']::text[],false,'{"seq":2,"concept":"K3-1-u1-C14","difficulty":2,"kind":"mc","stem":"지호는 「말만 잘하면 되지 표정은 상관없어.」라고 했어요. 알맞게 고친 말은 무엇일까요?","options":[{"t":"「표정과 몸짓도 마음을 전하니까 말과 맞춰야 해.」","correct":true},{"t":"「맞아, 표정은 상관없어.」","mis":"K3-1-u1-X16"},{"t":"「표정만 있으면 말은 필요 없어.」","mis":"K3-1-u1-X26"},{"t":"「목소리는 늘 크게만 하면 돼.」","mis":"K3-1-u1-X14"}],"explanation":["말","표정 · 몸짓","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
