INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L07_challenge#7','kor',3,1,'u1','L07','g3_1_kor_u1_L07_challenge','lesson_challenge','K3-1-u1-C14',3,'mc','auto','「처음 타는 두발자전거」를 역할로 읽을 때 마지막 「나 혼자 탔어!」에 어울리는 것은 무엇일까요?',ARRAY['K3-1-u1-X17','K3-1-u1-X13','K3-1-u1-X16']::text[],false,'{"seq":7,"concept":"K3-1-u1-C14","difficulty":3,"kind":"mc","stem":"「처음 타는 두발자전거」를 역할로 읽을 때 마지막 「나 혼자 탔어!」에 어울리는 것은 무엇일까요?","options":[{"t":"두 팔을 번쩍 들고 신나는 목소리로 읽는다","correct":true},{"t":"고개를 숙이고 작게 읽는다","mis":"K3-1-u1-X17"},{"t":"화난 목소리로 읽는다","mis":"K3-1-u1-X13"},{"t":"아무 표정 없이 웅얼거린다","mis":"K3-1-u1-X16"}],"explanation":["해냄","두 팔 번쩍","신나게"],"asset":{"type":"passage","lines":["예린이는 자전거 앞에서 입술을 꼭 깨물었어요.","손잡이를 잡은 손이 덜덜 떨렸어요.","「넘어지면 어떡하지?」 목소리가 점점 작아졌어요.","지호가 뒤에서 안장을 잡아 주며 씩 웃었어요.","「내가 꼭 잡고 있을게. 천천히 가 보자!」","몇 바퀴를 돈 뒤, 예린이는 두 팔을 번쩍 들었어요.","「나 혼자 탔어!」"],"title":"처음 타는 두발자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L07_challenge#8','kor',3,1,'u1','L07','g3_1_kor_u1_L07_challenge','lesson_challenge','K3-1-u1-C15',4,'essay','teacher','「처음 타는 두발자전거」에서 예린이의 처음 마음과 나중 마음을 쓰고, 각각 어떤 행동에서 알 수 있는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u1-C15","difficulty":4,"kind":"essay","stem":"「처음 타는 두발자전거」에서 예린이의 처음 마음과 나중 마음을 쓰고, 각각 어떤 행동에서 알 수 있는지 쓰세요.","answer_guide":{"answer":"예: 처음 — 넘어질까 봐 무섭고 걱정되었다(입술을 꼭 깨물고 손이 덜덜 떨림, 목소리가 작아짐). 나중 — 혼자 타게 되어 기뻤다(두 팔을 번쩍 들고 「나 혼자 탔어!」라고 외침).","scoring_points":["처음 마음과 행동을 썼는가","나중 마음과 행동을 썼는가","이야기 속 행동을 근거로 들었는가"]},"explanation":["처음","나중","행동"],"asset":{"type":"passage","lines":["예린이는 자전거 앞에서 입술을 꼭 깨물었어요.","손잡이를 잡은 손이 덜덜 떨렸어요.","「넘어지면 어떡하지?」 목소리가 점점 작아졌어요.","지호가 뒤에서 안장을 잡아 주며 씩 웃었어요.","「내가 꼭 잡고 있을게. 천천히 가 보자!」","몇 바퀴를 돈 뒤, 예린이는 두 팔을 번쩍 들었어요.","「나 혼자 탔어!」"],"title":"처음 타는 두발자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L07_challenge#9','kor',3,1,'u1','L07','g3_1_kor_u1_L07_challenge','lesson_challenge','K3-1-u1-C16',4,'essay','teacher','시험을 앞두고 걱정하는 짝에게 힘을 주려고 해요. 할 말과 함께 어울리는 표정 · 몸짓 · 목소리를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u1-C16","difficulty":4,"kind":"essay","stem":"시험을 앞두고 걱정하는 짝에게 힘을 주려고 해요. 할 말과 함께 어울리는 표정 · 몸짓 · 목소리를 쓰세요.","answer_guide":{"answer":"예: 「너는 열심히 공부했으니까 잘할 수 있을 거야!」 — 환하게 웃는 표정으로 어깨를 토닥이며 다정하고 밝은 목소리로 말한다.","scoring_points":["할 말을 썼는가","표정 · 몸짓을 썼는가","목소리를 썼는가"]},"explanation":["말","표정 · 몸짓","목소리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L07_challenge#10','kor',3,1,'u1','L07','g3_1_kor_u1_L07_challenge','lesson_challenge','K3-1-u1-C14',4,'essay','teacher','말과 표정이 어긋나면 어떤 일이 생길 수 있는지 예를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u1-C14","difficulty":4,"kind":"essay","stem":"말과 표정이 어긋나면 어떤 일이 생길 수 있는지 예를 들어 쓰세요.","answer_guide":{"answer":"예: 「고마워.」라고 하면서 팔짱을 끼고 찡그리면 친구는 내가 고마워하지 않는다고 느낄 수 있다. 그래서 말과 표정 · 몸짓을 함께 맞춰야 마음이 바르게 전해진다.","scoring_points":["어긋난 예를 들었는가","생길 수 있는 일을 썼는가","맞춰야 하는 까닭이 드러나는가"]},"explanation":["어긋난 예","생기는 일","맞추기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_basic#1','kor',3,1,'u1','L09','g3_1_kor_u1_L09_basic','lesson_basic','K3-1-u1-C17',1,'mc','auto','상황 속 인물이 되어 알맞은 표정 · 몸짓 · 목소리로 대화하는 것을 무엇이라고 할까요?',ARRAY['K3-1-u1-X20']::text[],false,'{"seq":1,"concept":"K3-1-u1-C17","difficulty":1,"kind":"mc","stem":"상황 속 인물이 되어 알맞은 표정 · 몸짓 · 목소리로 대화하는 것을 무엇이라고 할까요?","options":[{"t":"역할놀이","correct":true},{"t":"받아쓰기","mis":"K3-1-u1-X20"},{"t":"혼잣말","mis":"K3-1-u1-X20"},{"t":"숨바꼭질","mis":"K3-1-u1-X20"}],"explanation":["인물이 되어","대화","역할놀이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
