INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_basic#4','kor',3,1,'u1','L09','g3_1_kor_u1_L09_basic','lesson_basic','K3-1-u1-C18',1,'mc','auto','이사 간 친구를 놀이터에서 다시 만난 상황에 어울리는 표정은 무엇일까요?',ARRAY['K3-1-u1-X13','K3-1-u1-X16']::text[],false,'{"seq":4,"concept":"K3-1-u1-C18","difficulty":1,"kind":"mc","stem":"이사 간 친구를 놀이터에서 다시 만난 상황에 어울리는 표정은 무엇일까요?","options":[{"t":"환하게 웃는 반가운 표정","correct":true},{"t":"엉엉 우는 표정","mis":"K3-1-u1-X13"},{"t":"잔뜩 화난 표정","mis":"K3-1-u1-X13"},{"t":"아무 표정 없음","mis":"K3-1-u1-X16"}],"explanation":["다시 만남","반가움","환하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_basic#5','kor',3,1,'u1','L09','g3_1_kor_u1_L09_basic','lesson_basic','K3-1-u1-C18',2,'mc','auto','「역할놀이 상황 카드」 ㉡에 어울리는 말투는 무엇일까요?',ARRAY['K3-1-u1-X13','K3-1-u1-X20']::text[],false,'{"seq":5,"concept":"K3-1-u1-C18","difficulty":2,"kind":"mc","stem":"「역할놀이 상황 카드」 ㉡에 어울리는 말투는 무엇일까요?","options":[{"t":"걱정스럽고 다정한 말투","correct":true},{"t":"반갑고 신나는 말투","mis":"K3-1-u1-X13"},{"t":"비웃는 말투","mis":"K3-1-u1-X20"},{"t":"짜증 난 말투","mis":"K3-1-u1-X13"}],"explanation":["동생이 다침","걱정","다정하게"],"asset":{"type":"passage","lines":["㉠ 짝이 크레파스를 놓고 와서 빌려 달라고 한다.","㉡ 복도에서 동생이 넘어져 무릎을 다쳤다.","㉢ 이사 간 친구를 놀이터에서 다시 만났다.","㉣ 내가 실수로 모둠 친구의 그림을 찢었다."],"title":"역할놀이 상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_basic#6','kor',3,1,'u1','L09','g3_1_kor_u1_L09_basic','lesson_basic','K3-1-u1-C18',2,'mc','auto','「역할놀이 상황 카드」 ㉣에서 내가 할 알맞은 말은 무엇일까요?',ARRAY['K3-1-u1-X18','K3-1-u1-X21','K3-1-u1-X13']::text[],false,'{"seq":6,"concept":"K3-1-u1-C18","difficulty":2,"kind":"mc","stem":"「역할놀이 상황 카드」 ㉣에서 내가 할 알맞은 말은 무엇일까요?","options":[{"t":"(미안한 표정으로) 「정말 미안해. 같이 붙여 볼까?」","correct":true},{"t":"(웃으며) 「괜찮지?」","mis":"K3-1-u1-X18"},{"t":"(못 본 척) 아무 말도 안 하기","mis":"K3-1-u1-X21"},{"t":"(크게) 「네가 거기 둔 탓이야!」","mis":"K3-1-u1-X13"}],"explanation":["내 실수","사과","미안하게"],"asset":{"type":"passage","lines":["㉠ 짝이 크레파스를 놓고 와서 빌려 달라고 한다.","㉡ 복도에서 동생이 넘어져 무릎을 다쳤다.","㉢ 이사 간 친구를 놀이터에서 다시 만났다.","㉣ 내가 실수로 모둠 친구의 그림을 찢었다."],"title":"역할놀이 상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_basic#7','kor',3,1,'u1','L09','g3_1_kor_u1_L09_basic','lesson_basic','K3-1-u1-C18',2,'match','auto','상황과 어울리는 말투를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-1-u1-C18","difficulty":2,"kind":"match","stem":"상황과 어울리는 말투를 알맞게 이으세요.","pairs":[{"l":"짝에게 크레파스를 빌림","r":"미안하고 공손한 말투"},{"l":"동생이 넘어짐","r":"걱정스럽고 다정한 말투"},{"l":"이사 간 친구를 만남","r":"반갑고 신나는 말투"}],"mis":"K3-1-u1-X13","explanation":["빌림","다침","반가움"],"asset":{"type":"passage","lines":["㉠ 짝이 크레파스를 놓고 와서 빌려 달라고 한다.","㉡ 복도에서 동생이 넘어져 무릎을 다쳤다.","㉢ 이사 간 친구를 놀이터에서 다시 만났다.","㉣ 내가 실수로 모둠 친구의 그림을 찢었다."],"title":"역할놀이 상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_basic#8','kor',3,1,'u1','L09','g3_1_kor_u1_L09_basic','lesson_basic','K3-1-u1-C19',2,'mc','auto','역할놀이를 하면 좋은 점은 무엇일까요?',ARRAY['K3-1-u1-X20','K3-1-u1-X21','K3-1-u1-X16']::text[],false,'{"seq":8,"concept":"K3-1-u1-C19","difficulty":2,"kind":"mc","stem":"역할놀이를 하면 좋은 점은 무엇일까요?","options":[{"t":"실제 대화에서 상황에 맞게 표현할 자신감이 생긴다","correct":true},{"t":"친구를 놀릴 수 있다","mis":"K3-1-u1-X20"},{"t":"대사를 안 정해도 된다","mis":"K3-1-u1-X21"},{"t":"표정은 연습할 필요가 없어진다","mis":"K3-1-u1-X16"}],"explanation":["연습","이해","자신감"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_basic#9','kor',3,1,'u1','L09','g3_1_kor_u1_L09_basic','lesson_basic','K3-1-u1-C19',2,'mc','auto','역할놀이를 보는 친구들이 지킬 태도는 무엇일까요?',ARRAY['K3-1-u1-X20','K3-1-u1-X21']::text[],false,'{"seq":9,"concept":"K3-1-u1-C19","difficulty":2,"kind":"mc","stem":"역할놀이를 보는 친구들이 지킬 태도는 무엇일까요?","options":[{"t":"집중해서 보고 끝난 뒤 잘한 점을 말해 준다","correct":true},{"t":"떠들며 장난친다","mis":"K3-1-u1-X20"},{"t":"웃음거리로 삼는다","mis":"K3-1-u1-X20"},{"t":"보지 않고 딴짓한다","mis":"K3-1-u1-X21"}],"explanation":["보는 사람","집중","칭찬"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_basic#10','kor',3,1,'u1','L09','g3_1_kor_u1_L09_basic','lesson_basic','K3-1-u1-C17',3,'mc','auto','역할놀이에 대해 바르게 말한 친구는 누구일까요?',ARRAY['K3-1-u1-X20','K3-1-u1-X21','K3-1-u1-X16']::text[],false,'{"seq":10,"concept":"K3-1-u1-C17","difficulty":3,"kind":"mc","stem":"역할놀이에 대해 바르게 말한 친구는 누구일까요?","options":[{"t":"「상황 속 인물의 마음이 되어 실감 나게 말하는 연습이야.」","correct":true},{"t":"「웃기면 그게 제일 잘한 거야.」","mis":"K3-1-u1-X20"},{"t":"「대사는 그때그때 아무렇게나 해.」","mis":"K3-1-u1-X21"},{"t":"「표정은 안 지어도 돼.」","mis":"K3-1-u1-X16"}],"explanation":["인물의 마음","실감 나게","연습"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#1','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C18',2,'mc','auto','「하윤이네 역할놀이 대본」의 ㉮에 들어갈 표정 · 몸짓으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X20','K3-1-u1-X19']::text[],false,'{"seq":1,"concept":"K3-1-u1-C18","difficulty":2,"kind":"mc","stem":"「하윤이네 역할놀이 대본」의 ㉮에 들어갈 표정 · 몸짓으로 알맞은 것은 무엇일까요?","options":[{"t":"동생의 손을 잡아 일으키며 다정하게","correct":true},{"t":"깔깔 웃으며","mis":"K3-1-u1-X20"},{"t":"팔짱을 끼고","mis":"K3-1-u1-X19"},{"t":"딴 곳을 보며","mis":"K3-1-u1-X19"}],"explanation":["다친 동생","도와주기","다정하게"],"asset":{"type":"passage","lines":["상황 — ㉡ 복도에서 동생이 넘어져 무릎을 다쳤다.","역할 — 누나: 하윤 / 동생: 시우","하윤(걱정스러운 표정으로) 「많이 아프지? 일어날 수 있겠어?」","시우(울먹이며) 「응… 무릎이 따가워.」","하윤( ㉮ ) 「보건실에 같이 가자.」"],"title":"하윤이네 역할놀이 대본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#2','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C18',2,'mc','auto','「하윤이네 역할놀이 대본」에서 시우의 「응… 무릎이 따가워.」에 어울리는 목소리는 무엇일까요?',ARRAY['K3-1-u1-X13','K3-1-u1-X20']::text[],false,'{"seq":2,"concept":"K3-1-u1-C18","difficulty":2,"kind":"mc","stem":"「하윤이네 역할놀이 대본」에서 시우의 「응… 무릎이 따가워.」에 어울리는 목소리는 무엇일까요?","options":[{"t":"울먹이는 작은 목소리","correct":true},{"t":"신나게 외치는 목소리","mis":"K3-1-u1-X13"},{"t":"화난 목소리","mis":"K3-1-u1-X13"},{"t":"깔깔 웃는 목소리","mis":"K3-1-u1-X20"}],"explanation":["따가움","울먹임","작게"],"asset":{"type":"passage","lines":["상황 — ㉡ 복도에서 동생이 넘어져 무릎을 다쳤다.","역할 — 누나: 하윤 / 동생: 시우","하윤(걱정스러운 표정으로) 「많이 아프지? 일어날 수 있겠어?」","시우(울먹이며) 「응… 무릎이 따가워.」","하윤( ㉮ ) 「보건실에 같이 가자.」"],"title":"하윤이네 역할놀이 대본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#3','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C19',3,'mc','auto','역할놀이 도중 친구가 대사를 틀리자 다온이가 깔깔 웃으며 흉내 냈어요. 바른 태도는 무엇일까요?',ARRAY['K3-1-u1-X20','K3-1-u1-X21']::text[],false,'{"seq":3,"concept":"K3-1-u1-C19","difficulty":3,"kind":"mc","stem":"역할놀이 도중 친구가 대사를 틀리자 다온이가 깔깔 웃으며 흉내 냈어요. 바른 태도는 무엇일까요?","options":[{"t":"친구가 이어서 할 수 있게 기다리고, 끝난 뒤 잘한 점을 말해 준다","correct":true},{"t":"더 크게 흉내 낸다","mis":"K3-1-u1-X20"},{"t":"역할놀이를 그만둔다","mis":"K3-1-u1-X21"},{"t":"다른 친구들에게도 웃으라고 한다","mis":"K3-1-u1-X20"}],"explanation":["비웃기 ✗","기다리기","칭찬"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#4','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C18',3,'mc','auto','「역할놀이 상황 카드」 ㉠에서 크레파스를 빌려 주는 친구의 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X13','K3-1-u1-X21','K3-1-u1-X20']::text[],false,'{"seq":4,"concept":"K3-1-u1-C18","difficulty":3,"kind":"mc","stem":"「역할놀이 상황 카드」 ㉠에서 크레파스를 빌려 주는 친구의 말로 알맞은 것은 무엇일까요?","options":[{"t":"(웃으며) 「그래, 같이 쓰자. 필요할 때 또 말해.」","correct":true},{"t":"(짜증 내며) 「또 안 가져왔어?」","mis":"K3-1-u1-X13"},{"t":"(못 들은 척) 대답하지 않음","mis":"K3-1-u1-X21"},{"t":"(놀리며) 「너는 맨날 잊어버려.」","mis":"K3-1-u1-X20"}],"explanation":["빌려 주기","친절","다정하게"],"asset":{"type":"passage","lines":["㉠ 짝이 크레파스를 놓고 와서 빌려 달라고 한다.","㉡ 복도에서 동생이 넘어져 무릎을 다쳤다.","㉢ 이사 간 친구를 놀이터에서 다시 만났다.","㉣ 내가 실수로 모둠 친구의 그림을 찢었다."],"title":"역할놀이 상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#5','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C19',3,'mc','auto','역할놀이를 잘한 모둠은 어디일까요?',ARRAY['K3-1-u1-X20','K3-1-u1-X21','K3-1-u1-X13']::text[],false,'{"seq":5,"concept":"K3-1-u1-C19","difficulty":3,"kind":"mc","stem":"역할놀이를 잘한 모둠은 어디일까요?","options":[{"t":"역할과 대사를 미리 정하고, 상황에 맞는 표정으로 또렷하게 말한 모둠","correct":true},{"t":"대사 없이 웃기기만 한 모둠","mis":"K3-1-u1-X20"},{"t":"웅얼웅얼 작게 말해 들리지 않은 모둠","mis":"K3-1-u1-X21"},{"t":"슬픈 상황에서 신나게 춤춘 모둠","mis":"K3-1-u1-X13"}],"explanation":["준비","표정","또렷하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#6','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C17',3,'mc','auto','역할놀이를 하고 나서 하윤이가 「동생 마음이 어땠을지 알 것 같아.」라고 했어요. 역할놀이의 어떤 좋은 점일까요?',ARRAY['K3-1-u1-X20','K3-1-u1-X21','K3-1-u1-X16']::text[],false,'{"seq":6,"concept":"K3-1-u1-C17","difficulty":3,"kind":"mc","stem":"역할놀이를 하고 나서 하윤이가 「동생 마음이 어땠을지 알 것 같아.」라고 했어요. 역할놀이의 어떤 좋은 점일까요?","options":[{"t":"상대의 마음을 더 잘 이해하게 된다","correct":true},{"t":"친구를 웃길 수 있다","mis":"K3-1-u1-X20"},{"t":"대사를 외우지 않아도 된다","mis":"K3-1-u1-X21"},{"t":"표정 연습이 필요 없어진다","mis":"K3-1-u1-X16"}],"explanation":["동생 마음","이해","좋은 점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#7','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C18',3,'mc','auto','역할놀이 준비 차례로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X21','K3-1-u1-X20']::text[],false,'{"seq":7,"concept":"K3-1-u1-C18","difficulty":3,"kind":"mc","stem":"역할놀이 준비 차례로 알맞은 것은 무엇일까요?","options":[{"t":"상황 살피기 → 어울리는 표현 정하기 → 역할과 대사 정하기 → 역할놀이 하기","correct":true},{"t":"역할놀이 하기 → 상황 살피기","mis":"K3-1-u1-X21"},{"t":"대사 정하기 → 상황은 안 봄","mis":"K3-1-u1-X21"},{"t":"웃긴 장면 정하기 → 끝","mis":"K3-1-u1-X20"}],"explanation":["상황","표현 · 역할","하기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#8','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C18',4,'essay','teacher','「역할놀이 상황 카드」 ㉢을 골라 두 인물이 주고받을 대사를 쓰고, 어울리는 표정 · 목소리를 괄호에 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u1-C18","difficulty":4,"kind":"essay","stem":"「역할놀이 상황 카드」 ㉢을 골라 두 인물이 주고받을 대사를 쓰고, 어울리는 표정 · 목소리를 괄호에 쓰세요.","answer_guide":{"answer":"예: 나(환하게 웃으며 신나는 목소리로) 「어? 너 여기 웬일이야? 정말 반갑다!」 / 친구(놀라며 반가운 목소리로) 「할머니 댁에 왔다가 들렀어. 보고 싶었어!」","scoring_points":["두 인물의 대사를 썼는가","표정 · 목소리를 썼는가","상황에 어울리는가"]},"explanation":["대사","표정 · 목소리","반가움"],"asset":{"type":"passage","lines":["㉠ 짝이 크레파스를 놓고 와서 빌려 달라고 한다.","㉡ 복도에서 동생이 넘어져 무릎을 다쳤다.","㉢ 이사 간 친구를 놀이터에서 다시 만났다.","㉣ 내가 실수로 모둠 친구의 그림을 찢었다."],"title":"역할놀이 상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#9','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C19',4,'essay','teacher','역할놀이를 할 때 지킬 점 세 가지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u1-C19","difficulty":4,"kind":"essay","stem":"역할놀이를 할 때 지킬 점 세 가지를 쓰세요.","answer_guide":{"answer":"예: 상황에 맞는 표정과 목소리로 실감 나게 한다. 친구들이 잘 들을 수 있게 또렷하게 말한다. 친구를 비웃지 않고 언어 예절을 지킨다.","scoring_points":["지킬 점 세 가지를 썼는가","예절이나 또렷한 목소리가 들어갔는가","내용이 바른가"]},"explanation":["실감","또렷","예절"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L09_challenge#10','kor',3,1,'u1','L09','g3_1_kor_u1_L09_challenge','lesson_challenge','K3-1-u1-C17',4,'essay','teacher','「하윤이네 역할놀이 대본」을 이어서 하윤이와 시우가 보건실에 도착한 장면의 대사를 한 줄씩 쓰고, 어울리는 말투를 괄호에 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u1-C17","difficulty":4,"kind":"essay","stem":"「하윤이네 역할놀이 대본」을 이어서 하윤이와 시우가 보건실에 도착한 장면의 대사를 한 줄씩 쓰고, 어울리는 말투를 괄호에 쓰세요.","answer_guide":{"answer":"예: 하윤(공손한 말투로) 「선생님, 동생이 넘어져서 무릎을 다쳤어요.」 / 시우(조금 안심한 목소리로) 「누나, 같이 와 줘서 고마워.」","scoring_points":["두 인물의 대사를 썼는가","어울리는 말투를 썼는가","앞 장면과 이어지는가"]},"explanation":["이어지는 장면","대사","말투"],"asset":{"type":"passage","lines":["상황 — ㉡ 복도에서 동생이 넘어져 무릎을 다쳤다.","역할 — 누나: 하윤 / 동생: 시우","하윤(걱정스러운 표정으로) 「많이 아프지? 일어날 수 있겠어?」","시우(울먹이며) 「응… 무릎이 따가워.」","하윤( ㉮ ) 「보건실에 같이 가자.」"],"title":"하윤이네 역할놀이 대본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
