INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_basic#8','kor',3,1,'u1','L11','g3_1_kor_u1_L11_basic','lesson_basic','K3-1-u1-C23',2,'mc','auto','「소리 내어 읽어 볼 문장」 가운데 받침을 그대로 이어 읽는 것은 무엇일까요?',ARRAY['K3-1-u1-X24','K3-1-u1-X23']::text[],false,'{"seq":8,"concept":"K3-1-u1-C23","difficulty":2,"kind":"mc","stem":"「소리 내어 읽어 볼 문장」 가운데 받침을 그대로 이어 읽는 것은 무엇일까요?","options":[{"t":"㉢ 부엌에서","correct":true},{"t":"㉣ 부엌 안","mis":"K3-1-u1-X24"},{"t":"㉤ 무릎 위","mis":"K3-1-u1-X24"},{"t":"모두 이어 읽지 않음","mis":"K3-1-u1-X23"}],"explanation":["에서는","뜻 없는 말","그대로 이어"],"asset":{"type":"passage","lines":["㉠ 꽃이 피었다.","㉡ 무릎을 굽혔다.","㉢ 부엌에서 냄새가 난다.","㉣ 부엌 안이 따뜻하다.","㉤ 무릎 위에 고양이가 앉았다."],"title":"소리 내어 읽어 볼 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_basic#9','kor',3,1,'u1','L11','g3_1_kor_u1_L11_basic','lesson_basic','K3-1-u1-C25',2,'mc','auto','「꽃이」를 [꼬치]로 읽는다면 글자로는 어떻게 써야 할까요?',ARRAY['K3-1-u1-X25']::text[],false,'{"seq":9,"concept":"K3-1-u1-C25","difficulty":2,"kind":"mc","stem":"「꽃이」를 [꼬치]로 읽는다면 글자로는 어떻게 써야 할까요?","options":[{"t":"꽃이","correct":true},{"t":"꼬치","mis":"K3-1-u1-X25"},{"t":"꼳이","mis":"K3-1-u1-X25"},{"t":"꽂이","mis":"K3-1-u1-X25"}],"explanation":["읽기는 이어서","쓰기는","글자 그대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_basic#10','kor',3,1,'u1','L11','g3_1_kor_u1_L11_basic','lesson_basic','K3-1-u1-C21',3,'mc','auto','「알림장」의 낭송회에서 친구의 낭송이 끝났을 때 할 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X22']::text[],false,'{"seq":10,"concept":"K3-1-u1-C21","difficulty":3,"kind":"mc","stem":"「알림장」의 낭송회에서 친구의 낭송이 끝났을 때 할 말로 알맞은 것은 무엇일까요?","options":[{"t":"「뽀드득 부분을 실감 나게 읽어서 눈을 밟는 것 같았어!」","correct":true},{"t":"「왜 그렇게 읽었어? 이상해.」","mis":"K3-1-u1-X22"},{"t":"「빨리 끝내.」","mis":"K3-1-u1-X22"},{"t":"「나라면 더 잘했을 거야.」","mis":"K3-1-u1-X22"}],"explanation":["끝난 뒤","잘한 점","칭찬"],"asset":{"type":"passage","lines":["우리 반 시 낭송회","— 감각적 표현이 담긴 시를 하나씩 골라 와요.","— 시의 분위기에 어울리는 목소리 · 몸짓을 정해요.","— 친구의 낭송이 끝나면 잘한 점을 말해 줘요."],"title":"알림장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_challenge#1','kor',3,1,'u1','L11','g3_1_kor_u1_L11_challenge','lesson_challenge','K3-1-u1-C24',2,'mc','auto','「무릎 위」의 바른 발음은 무엇일까요?',ARRAY['K3-1-u1-X24','K3-1-u1-X23']::text[],false,'{"seq":1,"concept":"K3-1-u1-C24","difficulty":2,"kind":"mc","stem":"「무릎 위」의 바른 발음은 무엇일까요?","options":[{"t":"[무르뷔]","correct":true},{"t":"[무르퓌]","mis":"K3-1-u1-X24"},{"t":"[무릎위]","mis":"K3-1-u1-X23"},{"t":"[무릅위]","mis":"K3-1-u1-X23"}],"explanation":["위는 뜻 있는 낱말","ㅍ → ㅂ","[무르뷔]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_challenge#2','kor',3,1,'u1','L11','g3_1_kor_u1_L11_challenge','lesson_challenge','K3-1-u1-C20',2,'mc','auto','대화 만들기 놀이에서 「친구가 아플 때」 상황에 어울리는 말은 무엇일까요?',ARRAY['K3-1-u1-X13','K3-1-u1-X19']::text[],false,'{"seq":2,"concept":"K3-1-u1-C20","difficulty":2,"kind":"mc","stem":"대화 만들기 놀이에서 「친구가 아플 때」 상황에 어울리는 말은 무엇일까요?","options":[{"t":"「많이 아프니? 얼른 나아.」","correct":true},{"t":"「우아, 정말 고마워!」","mis":"K3-1-u1-X13"},{"t":"「빗소리가 시원해서 좋아!」","mis":"K3-1-u1-X13"},{"t":"「그것 봐, 내 말이 맞지?」","mis":"K3-1-u1-X19"}],"explanation":["아픈 친구","걱정","위로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_challenge#3','kor',3,1,'u1','L11','g3_1_kor_u1_L11_challenge','lesson_challenge','K3-1-u1-C23',3,'mc','auto','받침을 이어 읽는 까닭으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X25','K3-1-u1-X23','K3-1-u1-X24']::text[],false,'{"seq":3,"concept":"K3-1-u1-C23","difficulty":3,"kind":"mc","stem":"받침을 이어 읽는 까닭으로 알맞은 것은 무엇일까요?","options":[{"t":"받침 뒤에 뜻 없는 ㅇ이 오면 받침소리가 다음 글자로 넘어가기 때문이에요.","correct":true},{"t":"글자를 바꿔 써야 하기 때문이에요.","mis":"K3-1-u1-X25"},{"t":"아무 때나 끊어 읽어도 되기 때문이에요.","mis":"K3-1-u1-X23"},{"t":"뒤에 무엇이 오든 똑같이 넘어가기 때문이에요.","mis":"K3-1-u1-X24"}],"explanation":["뜻 없는 ㅇ","넘어감","이어 읽기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_challenge#4','kor',3,1,'u1','L11','g3_1_kor_u1_L11_challenge','lesson_challenge','K3-1-u1-C24',3,'mc','auto','「부엌에서」와 「부엌 안」의 발음이 다른 까닭은 무엇일까요?',ARRAY['K3-1-u1-X24','K3-1-u1-X23','K3-1-u1-X25']::text[],false,'{"seq":4,"concept":"K3-1-u1-C24","difficulty":3,"kind":"mc","stem":"「부엌에서」와 「부엌 안」의 발음이 다른 까닭은 무엇일까요?","options":[{"t":"「안」은 뜻을 지닌 낱말이라 받침을 대표 소리로 바꿔 이어 읽기 때문이에요.","correct":true},{"t":"두 말은 발음이 같아요.","mis":"K3-1-u1-X24"},{"t":"「부엌에서」를 끊어 읽어야 하기 때문이에요.","mis":"K3-1-u1-X23"},{"t":"글자를 [부어간]으로 바꿔 쓰기 때문이에요.","mis":"K3-1-u1-X25"}],"explanation":["에서 ↔ 안","뜻이 있나요?","바꿔 이어 읽기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
