INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_challenge#6','kor',3,1,'u1','L11','g3_1_kor_u1_L11_challenge','lesson_challenge','K3-1-u1-C20',3,'mc','auto','「알림장」의 낭송회를 준비하는 순서로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X09','K3-1-u1-X14','K3-1-u1-X22']::text[],false,'{"seq":6,"concept":"K3-1-u1-C20","difficulty":3,"kind":"mc","stem":"「알림장」의 낭송회를 준비하는 순서로 알맞은 것은 무엇일까요?","options":[{"t":"감각적 표현이 담긴 시 고르기 → 목소리 · 몸짓 정하기 → 낭송하기 → 친구의 잘한 점 말하기","correct":true},{"t":"낭송하기 → 시 고르기 → 끝","mis":"K3-1-u1-X09"},{"t":"목소리만 크게 정하기 → 낭송하기","mis":"K3-1-u1-X14"},{"t":"친구 낭송 흉내 내기 → 끝","mis":"K3-1-u1-X22"}],"explanation":["시 고르기","목소리 · 몸짓","낭송 · 칭찬"],"asset":{"type":"passage","lines":["우리 반 시 낭송회","— 감각적 표현이 담긴 시를 하나씩 골라 와요.","— 시의 분위기에 어울리는 목소리 · 몸짓을 정해요.","— 친구의 낭송이 끝나면 잘한 점을 말해 줘요."],"title":"알림장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
