INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_challenge#8','kor',3,1,'u1','L11','g3_1_kor_u1_L11_challenge','lesson_challenge','K3-1-u1-C22',4,'essay','teacher','「갈매기 · 파도 · 모래」가 있는 바닷가 장면을 서로 다른 감각을 살린 감각적 표현 세 가지로 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u1-C22","difficulty":4,"kind":"essay","stem":"「갈매기 · 파도 · 모래」가 있는 바닷가 장면을 서로 다른 감각을 살린 감각적 표현 세 가지로 설명하세요.","answer_guide":{"answer":"예: 갈매기가 끼룩끼룩 운다(소리). 파도가 하얗게 부서지며 출렁출렁 밀려온다(모습). 발바닥에 닿은 모래가 따끈따끈하다(느낌).","scoring_points":["감각적 표현 세 가지를 썼는가","서로 다른 감각을 살렸는가","장면에 어울리는가"]},"explanation":["소리","모습","느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_challenge#9','kor',3,1,'u1','L11','g3_1_kor_u1_L11_challenge','lesson_challenge','K3-1-u1-C23',4,'essay','teacher','「소리 내어 읽어 볼 문장」 에 나온 낱말 「꽃이 · 무릎을 · 부엌에서 · 부엌 안 · 무릎 위」의 발음을 모두 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u1-C23","difficulty":4,"kind":"essay","stem":"「소리 내어 읽어 볼 문장」 에 나온 낱말 「꽃이 · 무릎을 · 부엌에서 · 부엌 안 · 무릎 위」의 발음을 모두 쓰세요.","answer_guide":{"answer":"예: 꽃이 [꼬치] · 무릎을 [무르플] · 부엌에서 [부어케서] · 부엌 안 [부어간] · 무릎 위 [무르뷔]","scoring_points":["이어 읽는 낱말 세 개를 바르게 썼는가","안 · 위 앞 낱말 두 개를 바르게 썼는가","대괄호로 발음을 나타냈는가"]},"explanation":["그대로 이어","안 · 위 앞","바꿔 이어"],"asset":{"type":"passage","lines":["㉠ 꽃이 피었다.","㉡ 무릎을 굽혔다.","㉢ 부엌에서 냄새가 난다.","㉣ 부엌 안이 따뜻하다.","㉤ 무릎 위에 고양이가 앉았다."],"title":"소리 내어 읽어 볼 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_L11_challenge#10','kor',3,1,'u1','L11','g3_1_kor_u1_L11_challenge','lesson_challenge','K3-1-u1-C21',4,'essay','teacher','낭송회나 대화 놀이에서 친구와 협동한 경험을 떠올려(또는 상상해) 친구에게 해 줄 칭찬 한 가지와 도움말 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u1-C21","difficulty":4,"kind":"essay","stem":"낭송회나 대화 놀이에서 친구와 협동한 경험을 떠올려(또는 상상해) 친구에게 해 줄 칭찬 한 가지와 도움말 한 가지를 쓰세요.","answer_guide":{"answer":"예: 칭찬 — 「사락사락 부분을 작고 부드럽게 읽어서 눈 내리는 모습이 떠올랐어.」 / 도움말 — 「1연이 끝나고 조금 쉬어 읽으면 더 좋을 것 같아.」","scoring_points":["칭찬을 썼는가","도움말을 썼는가","친구를 배려하는 말인가"]},"explanation":["칭찬","도움말","협동"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
