INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_a#19','kor',3,1,'u1','','g3_1_kor_u1_review_a','unit_review','K3-1-u1-C12',3,'mc','auto','선생님께 칭찬을 듣고 작고 시무룩하게 「네….」라고 하면 어떻게 될까요?',ARRAY['K3-1-u1-X13','K3-1-u1-X12','K3-1-u1-X14']::text[],false,'{"seq":19,"concept":"K3-1-u1-C12","difficulty":3,"kind":"mc","stem":"선생님께 칭찬을 듣고 작고 시무룩하게 「네….」라고 하면 어떻게 될까요?","options":[{"t":"기쁜 마음이 잘 전해지지 않아 선생님이 걱정하실 수 있다","correct":true},{"t":"기쁜 마음이 가장 잘 전해진다","mis":"K3-1-u1-X13"},{"t":"목소리는 상관없다","mis":"K3-1-u1-X12"},{"t":"언제나 작게 말해야 한다","mis":"K3-1-u1-X14"}],"explanation":["칭찬","시무룩?","어긋남"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_a#20','kor',3,1,'u1','','g3_1_kor_u1_review_a','unit_review','K3-1-u1-C18',3,'mc','auto','「다온이의 바닷가 일기」로 역할놀이를 할 때 동생 역할에 어울리는 것은 무엇일까요?',ARRAY['K3-1-u1-X17','K3-1-u1-X20','K3-1-u1-X21']::text[],false,'{"seq":20,"concept":"K3-1-u1-C18","difficulty":3,"kind":"mc","stem":"「다온이의 바닷가 일기」로 역할놀이를 할 때 동생 역할에 어울리는 것은 무엇일까요?","options":[{"t":"고개를 숙이고 시무룩한 목소리로 「모래성이 무너졌어….」라고 한다","correct":true},{"t":"두 팔을 번쩍 들고 신나게 말한다","mis":"K3-1-u1-X17"},{"t":"깔깔 웃으며 장난친다","mis":"K3-1-u1-X20"},{"t":"대사 없이 가만히 있는다","mis":"K3-1-u1-X21"}],"explanation":["속상한 동생","표정 · 목소리","실감"],"asset":{"type":"passage","lines":["파도가 철썩철썩 바위에 부딪혔다.","짭짤한 바닷바람이 코끝을 간질였다.","발가락 사이로 고운 모래가 사르르 빠져나갔다.","동생이 모래성이 무너졌다며 고개를 푹 숙였다.","나는 동생 어깨를 토닥이며 다정하게 말했다.","「괜찮아, 같이 다시 쌓자!」","저녁에 바다 위로 붉은 해가 꼴깍 넘어갔다."],"title":"다온이의 바닷가 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_a#21','kor',3,1,'u1','','g3_1_kor_u1_review_a','unit_review','K3-1-u1-C24',3,'mc','auto','「부엌에서」는 [부어케서]인데 「부엌 안」은 [부어간]인 까닭은 무엇일까요?',ARRAY['K3-1-u1-X24','K3-1-u1-X23','K3-1-u1-X25']::text[],false,'{"seq":21,"concept":"K3-1-u1-C24","difficulty":3,"kind":"mc","stem":"「부엌에서」는 [부어케서]인데 「부엌 안」은 [부어간]인 까닭은 무엇일까요?","options":[{"t":"「안」은 뜻을 지닌 낱말이라 받침을 대표 소리로 바꿔 이어 읽기 때문이다","correct":true},{"t":"두 말의 발음은 같다","mis":"K3-1-u1-X24"},{"t":"「부엌에서」를 끊어 읽기 때문이다","mis":"K3-1-u1-X23"},{"t":"글자를 바꿔 쓰기 때문이다","mis":"K3-1-u1-X25"}],"explanation":["에서","안","뜻이 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_a#22','kor',3,1,'u1','','g3_1_kor_u1_review_a','unit_review','K3-1-u1-C1',3,'mc','auto','「생생하게 표현해요」를 가장 잘 정리한 친구는 누구일까요?',ARRAY['K3-1-u1-X26','K3-1-u1-X14','K3-1-u1-X20']::text[],false,'{"seq":22,"concept":"K3-1-u1-C1","difficulty":3,"kind":"mc","stem":"「생생하게 표현해요」를 가장 잘 정리한 친구는 누구일까요?","options":[{"t":"「감각적 표현과 표정 · 몸짓 · 목소리로 마음을 생생하게 전할 수 있어.」","correct":true},{"t":"「표현은 말 한 가지뿐이야.」","mis":"K3-1-u1-X26"},{"t":"「목소리는 크면 그만이야.」","mis":"K3-1-u1-X14"},{"t":"「역할놀이는 장난이야.」","mis":"K3-1-u1-X20"}],"explanation":["감각적 표현","표정 · 목소리","마음 전하기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_a#23','kor',3,1,'u1','','g3_1_kor_u1_review_a','unit_review','K3-1-u1-C4',4,'essay','teacher','「다온이의 바닷가 일기」에서 서로 다른 감각을 살린 감각적 표현 세 가지를 찾아, 각각 어떤 감각인지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u1-C4","difficulty":4,"kind":"essay","stem":"「다온이의 바닷가 일기」에서 서로 다른 감각을 살린 감각적 표현 세 가지를 찾아, 각각 어떤 감각인지 쓰세요.","answer_guide":{"answer":"예: 철썩철썩 — 귀로 들은 소리. 짭짤한 바닷바람 — 코로 맡은 냄새. 고운 모래가 사르르 — 피부로 느낀 감촉.","scoring_points":["감각적 표현 세 가지를 찾았는가","감각을 바르게 짝지었는가","서로 다른 감각인가"]},"explanation":["소리","냄새","피부"],"asset":{"type":"passage","lines":["파도가 철썩철썩 바위에 부딪혔다.","짭짤한 바닷바람이 코끝을 간질였다.","발가락 사이로 고운 모래가 사르르 빠져나갔다.","동생이 모래성이 무너졌다며 고개를 푹 숙였다.","나는 동생 어깨를 토닥이며 다정하게 말했다.","「괜찮아, 같이 다시 쌓자!」","저녁에 바다 위로 붉은 해가 꼴깍 넘어갔다."],"title":"다온이의 바닷가 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_a#24','kor',3,1,'u1','','g3_1_kor_u1_review_a','unit_review','K3-1-u1-C12',4,'essay','teacher','「응.」이라는 말을 기쁠 때와 미안할 때 각각 어떤 목소리로 말할지 쓰고, 뜻이 어떻게 달라지는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u1-C12","difficulty":4,"kind":"essay","stem":"「응.」이라는 말을 기쁠 때와 미안할 때 각각 어떤 목소리로 말할지 쓰고, 뜻이 어떻게 달라지는지 쓰세요.","answer_guide":{"answer":"예: 기쁠 때는 밝고 신나게 「응!」 하면 좋다는 뜻이 된다. 미안할 때는 작고 조심스럽게 「응….」 하면 잘못을 인정하는 마음이 담긴다.","scoring_points":["기쁠 때 목소리를 썼는가","미안할 때 목소리를 썼는가","뜻이 달라짐을 썼는가"]},"explanation":["기쁨","미안함","다른 뜻"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_a#25','kor',3,1,'u1','','g3_1_kor_u1_review_a','unit_review','K3-1-u1-C18',4,'essay','teacher','「친구가 내 책을 실수로 떨어뜨려 젖었다」는 상황의 역할놀이 대사를 두 인물이 한 번씩 주고받게 쓰고, 어울리는 표정 · 목소리를 괄호에 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u1-C18","difficulty":4,"kind":"essay","stem":"「친구가 내 책을 실수로 떨어뜨려 젖었다」는 상황의 역할놀이 대사를 두 인물이 한 번씩 주고받게 쓰고, 어울리는 표정 · 목소리를 괄호에 쓰세요.","answer_guide":{"answer":"예: 친구(미안한 표정으로 작게) 「정말 미안해. 내가 닦아 줄게.」 / 나(괜찮다는 듯 웃으며 다정하게) 「일부러 그런 거 아니잖아. 같이 말리자.」","scoring_points":["두 인물의 대사를 썼는가","표정 · 목소리를 썼는가","상황에 어울리는가"]},"explanation":["사과","받아 주기","표정 · 목소리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
