INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_b#21','kor',3,1,'u1','','g3_1_kor_u1_review_b','unit_review','K3-1-u1-C23',3,'mc','auto','「옷이 젖었다」의 「옷이」를 바르게 읽은 것은 무엇일까요?',ARRAY['K3-1-u1-X23','K3-1-u1-X24']::text[],false,'{"seq":21,"concept":"K3-1-u1-C23","difficulty":3,"kind":"mc","stem":"「옷이 젖었다」의 「옷이」를 바르게 읽은 것은 무엇일까요?","options":[{"t":"[오시]","correct":true},{"t":"[옷이]","mis":"K3-1-u1-X23"},{"t":"[옫이]","mis":"K3-1-u1-X23"},{"t":"[오디]","mis":"K3-1-u1-X24"}],"explanation":["받침 ㅅ","뒤 ㅇ","[오시]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_b#22','kor',3,1,'u1','','g3_1_kor_u1_review_b','unit_review','K3-1-u1-C20',3,'mc','auto','단원을 마치며 생활에서 실천할 일로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X04','K3-1-u1-X14','K3-1-u1-X22']::text[],false,'{"seq":22,"concept":"K3-1-u1-C20","difficulty":3,"kind":"mc","stem":"단원을 마치며 생활에서 실천할 일로 가장 알맞은 것은 무엇일까요?","options":[{"t":"일기에 감각적 표현을 살려 쓰고, 상황에 맞는 목소리로 대화한다","correct":true},{"t":"일기는 「재미있었다」만 쓴다","mis":"K3-1-u1-X04"},{"t":"누구에게나 크게만 말한다","mis":"K3-1-u1-X14"},{"t":"친구 표현을 놀린다","mis":"K3-1-u1-X22"}],"explanation":["일기","대화","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_b#23','kor',3,1,'u1','','g3_1_kor_u1_review_b','unit_review','K3-1-u1-C5',4,'essay','teacher','「운동장에서 놀았다.」를 감각적 표현 두 가지를 넣어 생생한 문장으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u1-C5","difficulty":4,"kind":"essay","stem":"「운동장에서 놀았다.」를 감각적 표현 두 가지를 넣어 생생한 문장으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 따사로운 햇살 아래 친구들과 운동장을 우다다 뛰어다니니 이마에 땀이 송골송골 맺혔다.","scoring_points":["감각적 표현 두 가지를 넣었는가","장면에 어울리는가","문장이 자연스러운가"]},"explanation":["햇살","뛰기","땀"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_b#24','kor',3,1,'u1','','g3_1_kor_u1_review_b','unit_review','K3-1-u1-C15',4,'essay','teacher','「다온이의 바닷가 일기」에서 동생의 마음을 짐작하고, 그렇게 짐작한 근거가 된 행동을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u1-C15","difficulty":4,"kind":"essay","stem":"「다온이의 바닷가 일기」에서 동생의 마음을 짐작하고, 그렇게 짐작한 근거가 된 행동을 쓰세요.","answer_guide":{"answer":"예: 동생은 모래성이 무너져서 속상했을 것이다. 고개를 푹 숙인 행동에서 그 마음을 알 수 있다.","scoring_points":["동생의 마음을 썼는가","근거가 된 행동을 썼는가","일기 내용에 맞는가"]},"explanation":["마음","근거","행동"],"asset":{"type":"passage","lines":["파도가 철썩철썩 바위에 부딪혔다.","짭짤한 바닷바람이 코끝을 간질였다.","발가락 사이로 고운 모래가 사르르 빠져나갔다.","동생이 모래성이 무너졌다며 고개를 푹 숙였다.","나는 동생 어깨를 토닥이며 다정하게 말했다.","「괜찮아, 같이 다시 쌓자!」","저녁에 바다 위로 붉은 해가 꼴깍 넘어갔다."],"title":"다온이의 바닷가 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_b#25','kor',3,1,'u1','','g3_1_kor_u1_review_b','unit_review','K3-1-u1-C24',4,'essay','teacher','「꽃이」와 「부엌 안」의 발음을 쓰고, 두 낱말을 이어 읽는 방법이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u1-C24","difficulty":4,"kind":"essay","stem":"「꽃이」와 「부엌 안」의 발음을 쓰고, 두 낱말을 이어 읽는 방법이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 꽃이 [꼬치] · 부엌 안 [부어간]. 「꽃이」는 뒤에 뜻 없는 ㅇ이 와서 받침을 그대로 이어 읽고, 「부엌 안」은 뒤에 뜻 있는 낱말이 와서 받침을 대표 소리 ㄱ으로 바꿔 이어 읽는다.","scoring_points":["두 발음을 바르게 썼는가","그대로 이어 읽기를 설명했는가","바꿔 이어 읽기를 설명했는가"]},"explanation":["[꼬치]","[부어간]","다른 점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
