INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#16','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C12',2,'mc','auto','「크고 밝게만 말하면 언제나 좋아.」를 바르게 고친 것은 무엇일까요?',ARRAY['K3-1-u1-X14','K3-1-u1-X12']::text[],false,'{"seq":16,"concept":"K3-1-u1-C12","difficulty":2,"kind":"mc","stem":"「크고 밝게만 말하면 언제나 좋아.」를 바르게 고친 것은 무엇일까요?","options":[{"t":"「상황에 따라 공손하거나 작게 말해야 할 때도 있어.」","correct":true},{"t":"「맞아, 언제나 크게.」","mis":"K3-1-u1-X14"},{"t":"「목소리는 상관없어.」","mis":"K3-1-u1-X12"},{"t":"「작게 말하면 늘 잘못이야.」","mis":"K3-1-u1-X14"}],"explanation":["언제나?","상황","골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#17','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C3',3,'mc','auto','하윤이는 「감각적 표현은 눈으로 본 것만 쓰는 거야.」라고 했어요. 알맞게 고친 말은 무엇일까요?',ARRAY['K3-1-u1-X06','K3-1-u1-X02','K3-1-u1-X04']::text[],false,'{"seq":17,"concept":"K3-1-u1-C3","difficulty":3,"kind":"mc","stem":"하윤이는 「감각적 표현은 눈으로 본 것만 쓰는 거야.」라고 했어요. 알맞게 고친 말은 무엇일까요?","options":[{"t":"「듣고 맡고 맛보고 만진 것도 감각적 표현으로 쓸 수 있어.」","correct":true},{"t":"「맞아, 눈으로 본 것만이야.」","mis":"K3-1-u1-X06"},{"t":"「감각적 표현은 이름이야.」","mis":"K3-1-u1-X02"},{"t":"「감각적 표현은 써도 달라지는 게 없어.」","mis":"K3-1-u1-X04"}],"explanation":["다섯 감각","모두","고친 말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#18','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C8',3,'mc','auto','「아기가 ( ) 잠들었다.」의 빈칸에 가장 어울리는 말은 무엇일까요?',ARRAY['K3-1-u1-X08','K3-1-u1-X07']::text[],false,'{"seq":18,"concept":"K3-1-u1-C8","difficulty":3,"kind":"mc","stem":"「아기가 ( ) 잠들었다.」의 빈칸에 가장 어울리는 말은 무엇일까요?","options":[{"t":"새근새근","correct":true},{"t":"쿵쾅쿵쾅","mis":"K3-1-u1-X08"},{"t":"철썩철썩","mis":"K3-1-u1-X07"},{"t":"데굴데굴","mis":"K3-1-u1-X08"}],"explanation":["잠든 아기","조용한 숨소리","새근새근"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#19','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C15',3,'mc','auto','「다온이의 바닷가 일기」에서 동생의 마음이 어떻게 바뀌었을지 짐작한 것으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u1-X17']::text[],false,'{"seq":19,"concept":"K3-1-u1-C15","difficulty":3,"kind":"mc","stem":"「다온이의 바닷가 일기」에서 동생의 마음이 어떻게 바뀌었을지 짐작한 것으로 알맞은 것은 무엇일까요?","options":[{"t":"속상함 → 다온이의 위로로 다시 힘이 남","correct":true},{"t":"기쁨 → 화남","mis":"K3-1-u1-X17"},{"t":"처음부터 끝까지 신남","mis":"K3-1-u1-X17"},{"t":"졸림 → 심심함","mis":"K3-1-u1-X17"}],"explanation":["고개 숙임","토닥 · 다정한 말","다시 힘"],"asset":{"type":"passage","lines":["파도가 철썩철썩 바위에 부딪혔다.","짭짤한 바닷바람이 코끝을 간질였다.","발가락 사이로 고운 모래가 사르르 빠져나갔다.","동생이 모래성이 무너졌다며 고개를 푹 숙였다.","나는 동생 어깨를 토닥이며 다정하게 말했다.","「괜찮아, 같이 다시 쌓자!」","저녁에 바다 위로 붉은 해가 꼴깍 넘어갔다."],"title":"다온이의 바닷가 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#20','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C21',3,'mc','auto','시 낭송회에서 친구에게 도움말을 줄 때 알맞은 말은 무엇일까요?',ARRAY['K3-1-u1-X22']::text[],false,'{"seq":20,"concept":"K3-1-u1-C21","difficulty":3,"kind":"mc","stem":"시 낭송회에서 친구에게 도움말을 줄 때 알맞은 말은 무엇일까요?","options":[{"t":"「연 사이에서 조금 쉬면 더 잘 들릴 것 같아.」","correct":true},{"t":"「너는 낭송을 못해.」","mis":"K3-1-u1-X22"},{"t":"「그만 읽어.」","mis":"K3-1-u1-X22"},{"t":"「아무 말 안 할래.」","mis":"K3-1-u1-X22"}],"explanation":["도움말","배려","구체적으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#21','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C25',3,'mc','auto','받아쓰기에서 「부엌에서 밥을 지었다」를 바르게 쓴 것은 무엇일까요?',ARRAY['K3-1-u1-X25']::text[],false,'{"seq":21,"concept":"K3-1-u1-C25","difficulty":3,"kind":"mc","stem":"받아쓰기에서 「부엌에서 밥을 지었다」를 바르게 쓴 것은 무엇일까요?","options":[{"t":"부엌에서 밥을 지었다","correct":true},{"t":"부어케서 바블 지었다","mis":"K3-1-u1-X25"},{"t":"부억에서 밥을 지었다","mis":"K3-1-u1-X25"},{"t":"부엌에서 바블 지었다","mis":"K3-1-u1-X25"}],"explanation":["읽기와","쓰기는","달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#22','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C22',3,'mc','auto','「다온이의 바닷가 일기」에 감각적 표현을 하나 더 넣는다면 가장 어울리는 것은 무엇일까요?',ARRAY['K3-1-u1-X05','K3-1-u1-X04','K3-1-u1-X02']::text[],false,'{"seq":22,"concept":"K3-1-u1-C22","difficulty":3,"kind":"mc","stem":"「다온이의 바닷가 일기」에 감각적 표현을 하나 더 넣는다면 가장 어울리는 것은 무엇일까요?","options":[{"t":"갈매기가 끼룩끼룩 하늘을 돌았다.","correct":true},{"t":"눈이 소복소복 쌓였다.","mis":"K3-1-u1-X05"},{"t":"바다가 있었다.","mis":"K3-1-u1-X04"},{"t":"모래성이라는 낱말을 썼다.","mis":"K3-1-u1-X02"}],"explanation":["바닷가","어울리는","감각적 표현"],"asset":{"type":"passage","lines":["파도가 철썩철썩 바위에 부딪혔다.","짭짤한 바닷바람이 코끝을 간질였다.","발가락 사이로 고운 모래가 사르르 빠져나갔다.","동생이 모래성이 무너졌다며 고개를 푹 숙였다.","나는 동생 어깨를 토닥이며 다정하게 말했다.","「괜찮아, 같이 다시 쌓자!」","저녁에 바다 위로 붉은 해가 꼴깍 넘어갔다."],"title":"다온이의 바닷가 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#23','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C9',4,'essay','teacher','좋아하는 시 한 편을 낭송한다고 생각하고, 어울리는 목소리와 강조할 부분 · 쉬어 읽을 곳을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u1-C9","difficulty":4,"kind":"essay","stem":"좋아하는 시 한 편을 낭송한다고 생각하고, 어울리는 목소리와 강조할 부분 · 쉬어 읽을 곳을 쓰세요.","answer_guide":{"answer":"예: 「눈 오는 운동장」을 신나고 밝은 목소리로 읽겠다. 「뽀드득뽀드득」을 또박또박 힘주어 강조하고, 1연과 2연 사이에서 잠깐 쉬어 읽겠다.","scoring_points":["어울리는 목소리를 썼는가","강조할 부분을 썼는가","쉬어 읽을 곳을 썼는가"]},"explanation":["목소리","강조","쉬기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#24','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C16',4,'essay','teacher','내가 다온이라면 동생을 어떻게 위로할지, 할 말과 함께 표정 · 몸짓 · 목소리를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u1-C16","difficulty":4,"kind":"essay","stem":"내가 다온이라면 동생을 어떻게 위로할지, 할 말과 함께 표정 · 몸짓 · 목소리를 쓰세요.","answer_guide":{"answer":"예: 「속상하지? 이번에는 더 튼튼하게 같이 쌓아 보자.」 — 걱정스러운 표정으로 동생 옆에 앉아 어깨를 감싸며 다정한 목소리로 말한다.","scoring_points":["할 말을 썼는가","표정 · 몸짓을 썼는가","목소리를 썼는가"]},"explanation":["말","표정 · 몸짓","목소리"],"asset":{"type":"passage","lines":["파도가 철썩철썩 바위에 부딪혔다.","짭짤한 바닷바람이 코끝을 간질였다.","발가락 사이로 고운 모래가 사르르 빠져나갔다.","동생이 모래성이 무너졌다며 고개를 푹 숙였다.","나는 동생 어깨를 토닥이며 다정하게 말했다.","「괜찮아, 같이 다시 쌓자!」","저녁에 바다 위로 붉은 해가 꼴깍 넘어갔다."],"title":"다온이의 바닷가 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_c#25','kor',3,1,'u1','','g3_1_kor_u1_review_c','unit_review','K3-1-u1-C21',4,'essay','teacher','시 낭송회에서 친구에게 해 줄 칭찬 한 가지와 도움말 한 가지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u1-C21","difficulty":4,"kind":"essay","stem":"시 낭송회에서 친구에게 해 줄 칭찬 한 가지와 도움말 한 가지를 쓰세요.","answer_guide":{"answer":"예: 칭찬 — 「끼룩끼룩 부분에서 팔을 펼치는 몸짓을 해서 갈매기가 나는 것 같았어.」 / 도움말 — 「마지막 줄을 조금 더 천천히 읽으면 더 좋을 것 같아.」","scoring_points":["칭찬을 썼는가","도움말을 썼는가","친구를 배려하는 말인가"]},"explanation":["칭찬","도움말","배려"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
