INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#16','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C15',2,'mc','auto','인물의 마음을 짐작할 때 살펴볼 것은 무엇일까요?',ARRAY['K3-1-u1-X16']::text[],false,'{"seq":16,"concept":"K3-1-u1-C15","difficulty":2,"kind":"mc","stem":"인물의 마음을 짐작할 때 살펴볼 것은 무엇일까요?","options":[{"t":"말 · 표정 · 몸짓 · 목소리","correct":true},{"t":"이름의 글자 수","mis":"K3-1-u1-X16"},{"t":"입은 옷 색깔만","mis":"K3-1-u1-X16"},{"t":"이야기의 쪽수","mis":"K3-1-u1-X16"}],"explanation":["말","표정","몸짓 · 목소리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#17','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C22',3,'mc','auto','같은 바닷가라도 「파도가 철썩철썩」과 「파도가 찰랑찰랑」은 어떻게 다르게 느껴질까요?',ARRAY['K3-1-u1-X26','K3-1-u1-X02','K3-1-u1-X08']::text[],false,'{"seq":17,"concept":"K3-1-u1-C22","difficulty":3,"kind":"mc","stem":"같은 바닷가라도 「파도가 철썩철썩」과 「파도가 찰랑찰랑」은 어떻게 다르게 느껴질까요?","options":[{"t":"철썩철썩은 세차게, 찰랑찰랑은 잔잔하게 느껴진다","correct":true},{"t":"둘은 느낌이 똑같다","mis":"K3-1-u1-X26"},{"t":"둘 다 감각적 표현이 아니다","mis":"K3-1-u1-X02"},{"t":"찰랑찰랑이 더 세차다","mis":"K3-1-u1-X08"}],"explanation":["철썩","찰랑","느낌 차이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#18','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C9',3,'mc','auto','낭송을 가장 잘한 친구는 누구일까요?',ARRAY['K3-1-u1-X09','K3-1-u1-X10']::text[],false,'{"seq":18,"concept":"K3-1-u1-C9","difficulty":3,"kind":"mc","stem":"낭송을 가장 잘한 친구는 누구일까요?","options":[{"t":"분위기에 맞는 목소리로 연 사이를 쉬고 「철썩철썩」을 힘주어 읽은 친구","correct":true},{"t":"아주 빠르게 한숨에 읽은 친구","mis":"K3-1-u1-X09"},{"t":"신나는 시를 울먹이며 읽은 친구","mis":"K3-1-u1-X10"},{"t":"눈으로만 읽은 친구","mis":"K3-1-u1-X09"}],"explanation":["분위기","쉬기","강조"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#19','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C13',3,'mc','auto','같은 부탁도 공손한 말투로 하면 좋은 까닭은 무엇일까요?',ARRAY['K3-1-u1-X15','K3-1-u1-X14','K3-1-u1-X12']::text[],false,'{"seq":19,"concept":"K3-1-u1-C13","difficulty":3,"kind":"mc","stem":"같은 부탁도 공손한 말투로 하면 좋은 까닭은 무엇일까요?","options":[{"t":"상대를 배려해 서로 기분 좋게 대화할 수 있기 때문이다","correct":true},{"t":"말투는 결과와 상관없기 때문이다","mis":"K3-1-u1-X15"},{"t":"크게 말해야 들어 주기 때문이다","mis":"K3-1-u1-X14"},{"t":"공손하면 뜻이 바뀌기 때문이다","mis":"K3-1-u1-X12"}],"explanation":["공손","배려","좋은 대화"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#20','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C1',3,'mc','auto','「생생하게 표현해요」에서 배운 표현 방법을 모두 쓴 것은 무엇일까요?',ARRAY['K3-1-u1-X04','K3-1-u1-X19','K3-1-u1-X14']::text[],false,'{"seq":20,"concept":"K3-1-u1-C1","difficulty":3,"kind":"mc","stem":"「생생하게 표현해요」에서 배운 표현 방법을 모두 쓴 것은 무엇일까요?","options":[{"t":"파도 소리를 「철썩철썩」이라 쓰고, 위로할 때 다정한 목소리와 토닥이는 몸짓을 함께 썼다","correct":true},{"t":"「바다가 있다」라고만 썼다","mis":"K3-1-u1-X04"},{"t":"말없이 등을 돌렸다","mis":"K3-1-u1-X19"},{"t":"모든 말을 크게 소리쳤다","mis":"K3-1-u1-X14"}],"explanation":["감각적 표현","목소리 · 몸짓","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#21','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C24',3,'mc','auto','「무릎 위」를 [무르퓌]로 읽은 친구에게 알맞은 도움말은 무엇일까요?',ARRAY['K3-1-u1-X24','K3-1-u1-X23','K3-1-u1-X25']::text[],false,'{"seq":21,"concept":"K3-1-u1-C24","difficulty":3,"kind":"mc","stem":"「무릎 위」를 [무르퓌]로 읽은 친구에게 알맞은 도움말은 무엇일까요?","options":[{"t":"「위는 뜻 있는 낱말이라 ㅍ을 ㅂ으로 바꿔 [무르뷔]로 읽어.」","correct":true},{"t":"「맞아, [무르퓌]야.」","mis":"K3-1-u1-X24"},{"t":"「끊어서 [무릎위]로 읽어.」","mis":"K3-1-u1-X23"},{"t":"「글자도 무르뷔로 써.」","mis":"K3-1-u1-X25"}],"explanation":["위","대표 소리 ㅂ","[무르뷔]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#22','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C16',3,'mc','auto','동생을 위로하는 다온이의 모습에서 배울 점은 무엇일까요?',ARRAY['K3-1-u1-X16','K3-1-u1-X13','K3-1-u1-X19']::text[],false,'{"seq":22,"concept":"K3-1-u1-C16","difficulty":3,"kind":"mc","stem":"동생을 위로하는 다온이의 모습에서 배울 점은 무엇일까요?","options":[{"t":"말과 몸짓, 목소리를 함께 맞추어 마음을 전했다","correct":true},{"t":"말만 하고 표정은 신경 쓰지 않았다","mis":"K3-1-u1-X16"},{"t":"크게 소리쳐 혼냈다","mis":"K3-1-u1-X13"},{"t":"못 본 척 지나갔다","mis":"K3-1-u1-X19"}],"explanation":["토닥","다정한 목소리","함께"],"asset":{"type":"passage","lines":["파도가 철썩철썩 바위에 부딪혔다.","짭짤한 바닷바람이 코끝을 간질였다.","발가락 사이로 고운 모래가 사르르 빠져나갔다.","동생이 모래성이 무너졌다며 고개를 푹 숙였다.","나는 동생 어깨를 토닥이며 다정하게 말했다.","「괜찮아, 같이 다시 쌓자!」","저녁에 바다 위로 붉은 해가 꼴깍 넘어갔다."],"title":"다온이의 바닷가 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#23','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C7',4,'essay','teacher','소리를 흉내 낸 말과 모양을 흉내 낸 말을 하나씩 넣어 비 오는 날 장면을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u1-C7","difficulty":4,"kind":"essay","stem":"소리를 흉내 낸 말과 모양을 흉내 낸 말을 하나씩 넣어 비 오는 날 장면을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 빗방울이 우산 위에 토독토독 떨어진다. 길가 웅덩이에 동그라미가 퐁퐁 생기며 빙글빙글 퍼져 나간다.","scoring_points":["소리를 흉내 낸 말을 넣었는가","모양을 흉내 낸 말을 넣었는가","장면에 어울리는가"]},"explanation":["소리","모양","두 문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#24','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C14',4,'essay','teacher','말과 표정 · 몸짓이 어긋나 마음이 잘못 전해질 수 있는 예를 하나 쓰고, 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u1-C14","difficulty":4,"kind":"essay","stem":"말과 표정 · 몸짓이 어긋나 마음이 잘못 전해질 수 있는 예를 하나 쓰고, 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 「미안해.」라고 하면서 웃으며 딴 곳을 보면 진심이 아닌 것처럼 보인다. 친구의 눈을 바라보며 미안한 표정과 진지한 목소리로 말해야 한다.","scoring_points":["어긋난 예를 썼는가","고치는 방법을 썼는가","말과 표정을 맞추는 것이 드러나는가"]},"explanation":["어긋남","고치기","맞추기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u1_review_d#25','kor',3,1,'u1','','g3_1_kor_u1_review_d','unit_review','K3-1-u1-C1',4,'essay','teacher','「생생하게 표현해요」에서 배운 것 가운데 가장 기억에 남는 것 두 가지를 쓰고, 생활에서 어떻게 쓸지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u1-C1","difficulty":4,"kind":"essay","stem":"「생생하게 표현해요」에서 배운 것 가운데 가장 기억에 남는 것 두 가지를 쓰고, 생활에서 어떻게 쓸지 쓰세요.","answer_guide":{"answer":"예: 감각적 표현과 상황에 맞는 목소리 · 말투가 기억에 남는다. 일기를 쓸 때 소리와 냄새를 살려 생생하게 쓰고, 친구가 속상할 때 다정한 목소리와 표정으로 위로하겠다.","scoring_points":["배운 것 두 가지를 썼는가","내용이 바른가","생활에서의 쓰임을 썼는가"]},"explanation":["기억에 남는 것","두 가지","생활 속으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
